programs.sol:
"""Approximate a sparse mixture of spelling and file-opening responses.

Strong negative responses mark byte-split Korean syllables (빠 and 뛰),
unfinished Runic letters after a space, and several source-file openings.
Chinese words for models, form, style and effects also get negative values.
Simple case/character classes provide a small first-token correction. Most
ordinary text stays near zero; this is not a complete account of the component.
"""
import unicodedata
import regex

READS = ()
APPEARANCE = {
    '模型': -1.25, '造型': -0.7,
    '风格': -0.7, '風格': -0.7, '效果': -0.45,
}


def unfinished(data):
    """Return only an incomplete UTF-8 suffix, never a text history."""
    for length in range(1, min(3, len(data)) + 1):
        part = data[-length:]
        if 0xC2 <= part[0] <= 0xF4:
            try:
                part.decode('utf8')
            except UnicodeDecodeError as error:
                if error.reason == 'unexpected end of data':
                    return part
            break
    return b''


def split_response(data, after_space):
    lead = data[0]
    width = 2 if lead < 0xE0 else 3 if lead < 0xF0 else 4
    if len(data) > width:
        return 0.0
    partial = len(data) < width
    char = (data + b'\x80' * (width - len(data))).decode('utf8', 'replace')
    if len(char) != 1 or char == '\ufffd':
        return 0.0
    if after_space:
        # Before the final byte, only a small syllable range is identifiable.
        if partial and data == '뛰'.encode()[:2]:
            return -10.4
        if partial and data == '빠'.encode()[:2]:
            return -2.03
        if not partial and char == '뛰':
            return -7.65
        if not partial and char == '빠':
            return -5.82
        if partial and regex.fullmatch(r'\p{Script=Runic}', char):
            return -3.5
    if regex.fullmatch(r'\p{Script=Hangul}', char):
        return -0.23 if partial else -0.03
    if regex.fullmatch(r'\p{Script=Runic}', char):
        return -0.08
    return 0.0


def first_token(s):
    """Coarse corrections for a position with no preceding text."""
    if s == '//\n':
        return -1.06
    if s == '//' or s in ('using', 'int'):
        return 1.03
    if s.startswith('/*'):
        return 0.98
    if s == 'package':
        return -0.52
    if s == '#':
        return 0.58
    if s == 'mm':
        return 2.1
    word = s.strip()
    if word.isdecimal():
        return -0.22
    if word.isascii() and word.isalpha():
        if len(word) == 1:
            return -0.26
        if word.isupper():
            return 0.14
        return -0.17 if word[0].isupper() else 0.04
    if word and all(unicodedata.category(c).startswith('P') for c in word):
        return 0.09
    return -0.05


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', b'', False, '')
    _, pos, prev, tail, spaced, marker = carry
    s, b = prefix.token_strings[-1], prefix.token_bytes[-1]
    value = first_token(s) if pos == 0 else -0.001
    if pos == 1:
        if prev == 'package' and s == ' com':
            value = -2.173
        elif prev == '<?' and s == 'php':
            value = -1.375
        elif prev == '1' and s == '2':
            value = -2.254
    if pos == 0:
        marker = next((m for m in ('\r', '^', '\\t')
                       if s and not s.replace(m, '')), '')
    if marker:
        marker = marker if not s.replace(marker, '') else ''
        if marker:
            value = {'\r': -1.77, '^': -1.87, '\\t': -1.44}[marker]
    combined = tail + b
    if tail and b and 0x80 <= b[0] < 0xC0:
        value = split_response(combined, spaced)
    new_tail = unfinished(combined)
    if new_tail and len(new_tail) <= len(b):
        spaced = b[:-len(new_tail)].endswith(b' ')
    for word, response in APPEARANCE.items():
        if s.endswith(word):
            value += response
            break
    return (doc, pos + 1, s, new_tail, spaced, marker), float(value)

"""Approximate a negative y/ya spelling and sound feature.

Strong cases are YAML, Japanese ya, the Mandarin syllable yang2, and Yang
or yard spellings, plus a few corresponding y letters in other scripts.
Recent text joins split spellings and recognizes yin-yang.
Most other tokens receive a nearly zero value. A separate positive response
covers bare carriage returns at the very beginning of a document.
"""
import re
from functools import lru_cache

import regex
from opencc import OpenCC
from pypinyin import Style, lazy_pinyin

READS = ()
SIMPLIFY = OpenCC('t2s')


@lru_cache(maxsize=4096)
def yang_character(char):
    """The second-tone Mandarin syllable yang, with a stronger surname response."""
    if not regex.fullmatch(r'\p{Script=Han}', char):
        return None
    if lazy_pinyin(char, style=Style.TONE3)[0] == 'yang2':
        return -7.5 if SIMPLIFY.convert(char) == '杨' else -3.1
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, yin, only_cr = '', False, True
    else:
        _, tail, yin, only_cr = carry
    token = prefix.token_strings[-1]
    low, history = token.lower(), tail.lower()
    word = re.sub(r'^[\W_]+', '', low)
    piece = token.strip()

    # Complete a character whose UTF-8 bytes were divided between tokens.
    if '\ufffd' in token:
        start = prefix.position
        while start > max(0, prefix.position - 2):
            if prefix.document_ids[start - 1] != doc:
                break
            start -= 1
        raw = b''.join(prefix.token_bytes[start:])
        char = raw.decode('utf-8', 'ignore')[-1:]
        if char and raw.endswith(char.encode('utf-8')):
            piece = char

    han_value = yang_character(piece) if len(piece) == 1 else None
    value = 0.002
    if token == '\r' and only_cr:
        value = 6.49
    elif han_value is not None:
        value = han_value
    elif piece.endswith(('や', 'ヤ')):
        value = -3.7 if piece.endswith('や') else -2.8
    elif piece in ('ユ', 'ゆ'):
        value = -0.8
    elif piece == '양':  # Korean yang
        value = -4.2
    # Persian/Arabic y letters respond mainly at a word boundary.
    elif piece in ('ی', 'ي') and (
        not tail or tail[-1:].isspace() or token[:1].isspace()
    ):
        value = -4.3 if piece == 'ی' else -1.1
    elif piece == 'ย':  # Thai y letter
        value = -2.1
    elif low == '.yaml':
        value = -1.65
    elif 'yaml' in low or word == 'yml':
        value = -3.5 if 'yaml' in low else -2.4
    elif history.endswith('y') and low.startswith('aml'):
        value = -3.8
    elif history.endswith('y') and low.startswith('ml'):
        value = -1.7
    elif word == 'yang':
        name = token.startswith(' Y') and (
            not tail or any(c.isupper() for c in tail)
        )
        value = -5.6 if yin or name else -0.8
    elif word == 'yard':
        value = -6.0 if token.lstrip().startswith('Yard') else -3.7
    elif word == 'yards':
        value = -1.7
    elif word.startswith('ya'):
        value = -0.55
    elif word == 'y':
        value = -0.7 if 'Y' in token else -0.4
        if token[:1] in '.-/':
            value = -1.0
        if yin and token == '-y':
            value = -3.8
    elif word.startswith('y'):
        value = -0.08

    if history.endswith('y') and token[:1].isalpha():
        if low == 'ang':
            value = -7.8
        elif low in ('ard', 'ards'):
            value = -6.8
        elif low.startswith(('ank', 'ash')) and not history.endswith(
            ('ay', 'ey', 'oy', 'uy')
        ):
            value = -4.0
        elif low.startswith('a') and re.search(r'(?:^|[^a-z])y$', history):
            value = min(value, -1.2)
        elif low.startswith(('a', 'e', 'o', 'u')) and value > -0.35:
            value = -0.35

    joined = tail + token
    yin = yin or bool(re.search(r'\byin\b', joined.lower()))
    only_cr = only_cr and token == '\r'
    return (doc, joined[-24:], yin, only_cr), float(value)

programs.haiku:
"""Layer 1 MLP down_proj component 3521: a 'yang / ya' sound detector.

The component is negative on tokens that are, or spell, the sound "ya" / "yang":
Chinese and Japanese characters read yáng or ya (杨 扬 羊 阳 陽 洋, や, ヤ, ย),
capitalised Yang, the words yard and yaml/YAML, the config suffixes .yml/.yaml,
and the completion pieces ("ang", "ard", "ank", "aml") right after a token ending
in y (yin-y|ang, Y|ank). A bare 'y' or 'Y' letter (any script) gets a weaker
negative value. Everything else predicts 0.
"""

READS = ()

YANG_CHARS = set("杨扬羊阳陽洋양ย") | set("やヤ")
WORD_VALUES = {"yang": -1.5, "yard": -3.5, "yards": -2.5, "yaml": -3.5, "yam": -3.0}
Y_LETTERS = {"y": -0.3, "ي": -0.7, "י": -1.6, "ی": -0.3}
COMPLETIONS = {"ang", "ard", "ards", "ank", "anks", "ash", "aw", "aml"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    stripped = tok.strip()
    bare = stripped.lstrip(".-/_").lower()
    if stripped in YANG_CHARS:
        return None, -3.6
    if stripped == "Yang":
        return None, -4.8
    if bare in WORD_VALUES:
        return None, WORD_VALUES[bare]
    if stripped in (".yml", ".yaml") or bare in ("aml", "yml"):
        return None, -2.5 if "yml" in stripped or bare == "aml" else -1.5
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lstrip(".-/_").lower() if same_doc else ""
    if bare in COMPLETIONS and prev.endswith("y"):
        return None, -5.5
    if stripped == "Y":
        return None, -0.9 if tok.startswith(" ") else -0.5
    if bare in Y_LETTERS:
        return None, Y_LETTERS[bare]
    return None, 0.0

programs.sol:
"""Detect disrupted Latin-script words, especially OCR long-s errors.

Familiarity is the frequency of the commonest corpus word beginning with
an ASCII-letter fragment (English, German, French or Spanish). A fragment
is suspicious if f-to-s repair, a restored printing ligature, or removing
an internal gap makes it familiar. Font glyphs, printed ligatures and
bracket insertions are additional cues. Most positions stay near zero;
there are separate baselines for a few literal code lead-ins at document
starts, other document starts, and the bare import keyword.
These rules capture only part of the component's token-specific behavior.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import top_n_list, zipf_frequency

READS = ()
PREFIX = {}
WORDS = {}
for language in ('en', 'de', 'fr', 'es'):
    for word in top_n_list(language, 60000):
        if not (word.isascii() and word.isalpha() and word.islower()):
            continue
        frequency = zipf_frequency(word, language)
        WORDS[word] = max(WORDS.get(word, 0), frequency)
        for end in range(1, len(word) + 1):
            fragment = word[:end]
            PREFIX[fragment] = max(PREFIX.get(fragment, 0), frequency)


def familiar(word):
    return PREFIX.get(word.lower(), 0.0)


@lru_cache(maxsize=50000)
def long_s_gain(word):
    word = word.lower()
    repaired = familiar(word.replace('f', 's'))
    for i, letter in enumerate(word):
        if letter == 'f':
            repaired = max(repaired, familiar(word[:i] + 's' + word[i+1:]))
    return max(0.0, repaired - familiar(word))


@lru_cache(maxsize=50000)
def lost_ligature(word):
    """Does restoring a lost printing ligature produce a common whole word?"""
    word = word.lower()
    best = 0.0
    if 5 <= len(word) <= 20 and familiar(word) < 3.0:
        for i in range(len(word) + 1):
            for letters in ('fi', 'fl', 'ff', 'ffi', 'ffl'):
                repaired = word[:i] + letters + word[i:]
                best = max(best, WORDS.get(repaired, 0))
    return best


def measurements(text, token):
    plain = (text + token)[-120:]
    m = re.search(r'[A-Za-z]+$', plain)
    word = m.group() if m else ''
    continuing = bool(re.search(r'[A-Za-z]$', text)
                      and token[:1].isascii() and token[:1].isalpha())
    old_gain = long_s_gain(word) if continuing else 0.0
    # Both halves should be less familiar than their unbroken combination.
    gap = re.search(r'([A-Za-z]+)[ \n\t-]+([A-Za-z]+)$', plain)
    join_gain = 0.0
    broken = False
    missing = lost_ligature(word) if continuing else 0.0
    if gap and word:
        left, right = (s.lower() for s in gap.groups())
        missing = max(missing, lost_ligature(left + right))
        broken = (len(left) >= 4 and WORDS.get(left, 0) < 1
                  and familiar(left + right) > 3.0)
        join_gain = max(0.0, familiar(left + right)
                        - max(WORDS.get(left, 0), WORDS.get(right, 0)))
    bracket = re.search(r'\[([A-Za-z])\]([A-Za-z]+)$', plain)
    bracket_gain = (familiar(''.join(bracket.groups())) - familiar(word)
                    if bracket else 0.0)
    latin_piece = token[:1].isascii() and token[:1].isalpha()
    font_glyph = latin_piece and bool(text) and (
        unicodedata.category(text[-1]) == 'Co')
    ligature = latin_piece and bool(set(text[-3:]) & set('ﬁﬂﬃﬄﬀ'))
    return (plain, word, old_gain, join_gain, bracket_gain, font_glyph,
            ligature, missing, broken)


def step(carry, prefix, upstream):
    first = (carry is None or prefix.document_ids[-1] != carry[0])
    raw = b'' if first else carry[1]
    text = raw.decode('utf-8', errors='replace')
    token = prefix.token_strings[-1]
    measured = measurements(text, token)
    (_, word, old, join, bracket, glyph, ligature,
     missing, broken) = measured
    value = -0.001
    if first:
        value = -0.06
        # Literal code lead-ins have separate document-initial baselines.
        if token == 'var':            # variable-declaration keyword
            value = 1.2
        elif token == 'Python':       # language heading
            value = 0.75
        elif token == '--':
            value = 1.3
        elif token == '//\n':
            value = 5.5
    if token == 'import':
        value = -0.12
    if len(word) >= 4 and (old > 3.5 or (old > 2.5 and len(word) >= 6)):
        value = 0.3 if old < 4.75 else 0.45
        if word[:1].isupper():
            value *= 0.1
    if broken:
        value = max(value, 0.25)
    if join > 1.25:
        value = max(value, 0.4)
    if missing > 4.2:
        value = max(value, 0.35)
    if bracket > 1.0:
        value = max(value, 0.35)
    if glyph:
        value = max(value, 0.7)
    if ligature:
        value = max(value, 0.3)
    return (prefix.document_ids[-1],
            (raw + prefix.token_bytes[-1])[-256:]), value

"""Detect split indefinite pronouns and boundaries of first list items.

Negative responses mark completion of split someone/anybody/nothing/etc.,
including spaced spellings. Positive responses mark first-item punctuation,
commas after yes/no/sure, quantified phrases, and Chinese uses of 'one'.
There are small additional rules for 'one' and first-section numbering.
Unrecognized positions get zero; only recent document text is carried.
"""
import re
import regex

READS = ()

STRENGTH = {'no': 3.6, 'any': 4.4, 'some': 7.7,
            'every': 6.4, 'else': 6.5}
COMPOUND = re.compile(
    r'\b(no|any|some|every|else)\s*(one|ones|body|thing|where)$')


def response(token, previous, text):
    part = token.strip().lower()
    before = text.replace('\\n', '\n').replace('\\t', '\t')
    before = re.sub(r'-[ \t]*\n', '', before).rstrip(' \t').lower()
    # Recognize a pronoun whose spelling began before this token.
    match = COMPOUND.search(before + token.lower())
    if match and match.start() + len(match[1]) - 1 <= len(before):
        root, ending = match.groups()
        if root != 'else' or ending == 'where':
            strength = STRENGTH[root]
            if len(before) < match.start() + len(root):
                strength *= 0.35
            if root == 'some' and ending in {'body', 'ones'}:
                strength *= 0.82
            if token.strip().isupper():
                strength *= 0.7
            if root == 'any' and ending == 'thing':
                strength = 6.5 if token.startswith(' ') else 2.7
            return -strength

    prev = previous.strip()
    low = prev.lower()
    if token == ',' and low in {'yes', 'no', 'sure'}:
        if low == 'sure':
            return 3.0 if prev[0].isupper() else 0.0
        if low == 'no':
            return 2.3 if prev[0].isupper() else 1.5
        return 1.75 if prev[0].isupper() else 0.65

    line = text.replace('\\n', '\n').rsplit('\n', 1)[-1]
    if token == '1' and re.fullmatch(
            r'\s*[-*]?\s*\d+(?:\.\d+)*\.', line):
        return 0.35
    if text and token == '1' and not line.strip():
        if regex.search(r'\p{Script=Han}', text[-100:]):
            return -1.1
        return -0.7 if text.rstrip().endswith(':') else -0.18

    if prev in {'1', 'a', 'A', 'i', 'I', '(a', '(A', '(i'}:
        if token in {'.', ')', ':', '、', '.)'}:
            at_start = bool(re.fullmatch(r'\s*\(?[1aAiI]', line))
            if at_start:
                return 1.2 if token == ')' else 1.0
            if token == ')' and re.search(r'\([1aAiI]$', text):
                return 0.55
            if prev == '1' and re.search(r'\d1$', text):
                return 0.0
            if token == '.' and prev in {'a', 'A', 'I'}:
                return 0.3
            if prev == '1':
                return 0.12

    quantity = re.search(
        r'\b(no|any|every|some|each|which)\s+'
        r'(one|pair|number|amount|combination)$', before)
    if part == 'of' and quantity:
        quantifier, noun = quantity.groups()
        if noun == 'amount':
            return 11.5 if quantifier == 'no' else 4.5
        if noun == 'number':
            return 3.2
        return 2.5 if noun == 'one' else 1.8
    if (part == 'given' and low == 'any' or
            part == 'hand' and low == 'one' or
            part == 'point' and low in {'any', 'some'}):
        return 0.9
    if part == 'amount' and low == 'no':
        return 4.2
    if part == 'two' and low in {'no', 'any', 'every'}:
        return 3.4 if low == 'no' else 0.9
    if part == 'one' and low in {'which', 'each'}:
        return 0.9
    if part == 'time' and low in {'some', 'no'}:
        return -0.8
    if part in {'how', 'what'} and low in {'some', 'any'}:
        return -3.0
    if part == 'place' and low == 'no':
        return -2.7

    if token.startswith('一') and text:
        if text[-1] in '每某哪任同':
            return 3.5
        if text[-1] in '下上那这這':
            return 1.3
    if token.startswith('同一'):
        return 1.6
    if part == 'one' and token.startswith(' '):
        return 0.15
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, text = '', ''
    else:
        _, previous, text = carry
    token = prefix.token_strings[-1]
    value = response(token, previous, text)
    return (doc, token, (text + token)[-180:]), value

"""Approximate a document-onset pulse and smaller whitespace pulses.

Onset strength uses token length, case, script, English word frequency,
articles, digits, and familiar source/markup delimiters. These are coarse
categories rather than a table of individual words. The pulse persists
through an unbroken repetition of the opening token. Elsewhere only a
single space/tab/nonbreaking space following non-newline whitespace
gets a pulse.
Document boundaries reset the state.
"""
from functools import lru_cache
import regex
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=8192)
def onset(token):
    word = token.strip()
    if token.startswith('<|') and token.endswith('|>'):
        return 5.4
    if not word:
        if '\t' in token:
            return 0.8
        if '\n' in token:
            return 2.2 if token.startswith(' ') else 4.1
        return 3.8
    if word.isdecimal():
        if not word.isascii():
            return 3.5
        digit = int(word)
        if digit in (0, 9):
            return 1.8
        return 6.4 - 0.8 * digit if digit < 3 else 3.6
    if regex.fullmatch(r'\p{Han}+', word):
        return 4.2
    if regex.fullmatch(r'[\p{Hiragana}\p{Katakana}]+', word):
        return 5.0
    # Common ways to open headings, source files and comments.
    if word.startswith('#!'):
        return 17.0
    if word.startswith('#'):
        if word.strip('#'):
            return 9.0
        return 23.0 if word == '#' else 22.0
    if word.startswith('//'):
        return 16.0
    if word.startswith('/*'):
        return 12.0
    if not any(c.isalpha() for c in word):
        if word.startswith(('"""', "'''")):
            return 15.0
        if word[0] in '([{':
            return 8.0 if token.startswith(' ') else 14.0
        if word[0] in '"\'':
            return 5.0 if token.startswith(' ') else 11.5
        if len(word) > 1 and len(set(word)) == 1 and word[0] not in '.?!':
            return 10.0
        return 4.0
    if not regex.fullmatch(r'\p{Latin}+', word):
        return 8.0 if word.istitle() else 5.0
    f = zipf_frequency(word, 'en')
    value = 7.1 + 0.48 * f - 0.54 * min(len(word), 12)
    if token.startswith(' '):
        value -= 1.9
    if word.istitle():
        value += 0.25 if token.startswith(' ') else 5.75
    if word.isupper():
        value += 2.7
    if word.lower() in ('a', 'an', 'the'):
        value += 7.4
    return max(1.0, value)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    token_id = prefix.token_ids[-1]
    opening_run = first or (carry[2] and carry[3] == token_id)
    if opening_run:
        value = onset(token)
    elif (token in (' ', '\t', '\xa0') and carry[1].isspace()
          and '\n' not in carry[1] and '\r' not in carry[1]):
        if token == ' ':
            value = 0.65 if carry[1] == ' ' else 1.65
        elif token == '\t':
            value = 0.85 if carry[1] == '\t' else 1.1
        else:
            value = 1.6
    else:
        value = 0.0
    return (doc, token, opening_run, token_id), value

programs.haiku:
"""Layer 1 MLP down-projection, component 3526: a document-start detector.

In plain terms, this component is almost silent everywhere except at the first token of
each document (a packed row holds several documents; a new one starts where document_ids
changes). There its size depends on what that first token is:
  - a capitalised word: about 20 minus 1.5 per character (a lone "A" ~19, "The" ~15,
    a long name ~7); an article (" the", " a", "The", "A"): about 15
  - a lowercase word: about 11 minus 1.1 per character (short fragments are higher);
    punctuation and symbols ("#", "(", ","): about 7
  - a space-led ordinary word (" of", " and"): about 5
  - a digit or a whitespace token: about 3.5

Two smaller effects inside a document:
  - a whitespace token that follows another whitespace token (the later pieces of an
    indentation or space run, e.g. the " " after "    "): about 1.5
  - the repeated middle-dot token "··": about 11

Everywhere else the component is 0.
"""

READS = ()

ARTICLES = {" the", " a", " an", " my", " this", " our", " his", " her", " its", " their",
            " The", " A", " An", " My", " This"}


def first_token_value(s):
    """Activation when the token s is the first token of a document."""
    if s in ARTICLES:
        return 15.0
    if s.isspace():
        return 3.5
    if s[0].isalpha():
        if s[0].isupper():
            return max(7.0, 20.0 - 1.5 * len(s))
        return max(4.5, 11.0 - 1.1 * len(s))
    if s[0] == " " and len(s) > 1 and s[1].isalpha():
        return 5.0
    if s.isdigit():
        return 3.5
    return 7.0


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if len(prefix.token_ids) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, first_token_value(tok)
    if tok == "··":
        return carry, 11.0
    if tok.isspace() and prefix.token_strings[-2].isspace():
        return carry, 1.5
    return carry, 0.0

programs.sol:
"""A detector for historical dates, especially parenthetical birth dates.

The main response is negative on the third digit of a potential 1300--1999
calendar year. Month names, temporal prepositions and lifespan parentheses
strengthen it. The response weakens for later twentieth-century decades.
Neighboring digits have smaller responses; birth-date spaces and range
dashes have additional responses.
Everything else is zero. Only a bounded text suffix is carried between tokens;
it is cleared when the document changes.
"""
import re
import unicodedata
from calendar import month_name, month_abbr

READS = ()
MONTHS = '|'.join(x for x in (*month_name, *month_abbr) if x)
MONTH = re.compile(r'\b(?:' + MONTHS + r')\b')
YEAR_SLOT = re.compile(
    r'(?:\b\d{1,2}\s+(?:' + MONTHS + r')\.?|'
    r'\b(?:' + MONTHS + r')\.?\s+\d{1,2},?)\s*$')
TIME_WORD = re.compile(
    r'\b(?:in|In|from|since|until|en|im|von|year)\s*$')
BARE_YEARS = re.compile(r'\s*(?:[12]\d{3}\s*[-–—]\s*)?')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    t = unicodedata.normalize('NFKC', token)
    b = unicodedata.normalize('NFKC', raw)
    text = b + t
    bracket = b[b.rfind('(') + 1:]
    paren = ('(' in b and b.rfind('(') > b.rfind(')')
             and len(bracket) < 90)
    born = bool(re.search(r'\b[Bb]orn\b[^).;\n]{0,65}$', b))
    month = bool(MONTH.search(b[-35:]))
    birth_date = born or (month and paren)
    digits = re.search(r'[0-9]+$', text)
    value = 0.0

    if t.isdecimal() and digits:
        number = digits[0]
        n = len(number)
        before_number = text[:-n]
        year_slot = bool(YEAR_SLOT.search(before_number[-45:]))
        if birth_date and n <= 2:
            if year_slot:
                value = -2.95 if number.startswith('1') else 0.0
            else:
                value = -1.21
        if n == 2 and number in ('16', '17', '18', '19'):
            value -= 0.17
        if n == 3:
            decade = int(number)
            if 130 <= decade < 200:
                # A soft historical-date strength, not an exact year lookup.
                age = min(1.0, (200 - decade) / 8.0)
                strength = age * age
                value = -0.11 if decade < 180 else -1.56 * strength
                if month:
                    value -= 3.43 * strength + 0.27
                if birth_date:
                    value -= 2.34 * age + 1.57
                elif paren:
                    value -= 0.47 * strength
                opening = before_number[before_number.rfind('(') + 1:]
                if paren and BARE_YEARS.fullmatch(opening):
                    value -= 1.57 * strength
                if TIME_WORD.search(before_number[-20:]):
                    value -= 2.84 * strength
                if before_number and (before_number[-1].isalnum()
                                      or before_number[-1] in '.,/$£€'):
                    value += 0.55 * strength
            elif 201 <= decade <= 202 and month:
                value = -0.35
        if n == 4 and 1300 <= int(number) < 2000:
            value = -0.18 - (1.52 if birth_date else 0.0)

    elif t.strip() in ('-', '–', '—'):
        year = re.search(r'\b[12][0-9]{3}\s*$', b)
        # Quoted dates in code are not treated as lifespan ranges.
        if year and (year.start() == 0 or b[year.start()-1] not in '\"\'=/'):
            value = -1.19 - 5.74 * paren - 3.23 * birth_date
    elif t.isspace() and birth_date:
        if YEAR_SLOT.search(b[-45:]):
            value = -2.10
        elif month:
            value = -0.73
        elif re.search(r'\b[Bb]orn$', b):
            value = -1.13
    elif t == ',' and birth_date:
        value = -0.28
    elif t == ')' and birth_date:
        value = -0.34
    elif t.strip() == 'in' and birth_date and re.search(r'\d{4},?\s*$', b):
        value = -4.90
    if t.strip() == 'in' and re.search(r'\bborn$', b):
        value -= 1.82
    if t.strip().lower() == 'born':
        value -= 0.27 + 1.41 * paren
    return (doc, (raw + token)[-180:]), float(value)

"""A short-range lexical-collocation detector.

The largest English responses finish 'head/ahead/back of', 'share(s) of'
and 'Bank of'. Banking/reserve vocabulary and the Chinese storage character
also excite it. 'Best of' has the opposite sign. Chinese/Japanese head
compounds are a smaller response. A tiny byte buffer recognizes a storage
character even when it spans tokens. Other constructions are left at zero:
this is a lexical approximation, not a general semantic model.
