READS = ()

# Weights are at the final token of these familiar 'of' constructions.
OF = {
    'head': 7.0, 'heads': 3.0, 'ahead': 4.2,
    'back': 2.7, 'rear': 4.8, 'front': 0.25,
    'top': 0.3, 'bottom': 0.4,
    'share': 6.9, 'shares': 4.8, 'bank': 4.2,
    'rest': 1.9, 'last': 4.6, 'first': 1.0,
    'best': -1.7, 'result': -0.34,
    'president': 0.6, 'director': 0.7, 'leader': 1.0,
    'founder': 0.75, 'founders': 0.75,
    'reserve': 2.8, 'reserves': 2.8, 'store': 2.8,
