    elif lower == 'share':
        if before in ('a', 'any', 'his', 'her', 'their', 'our', 'my', 'your'):
            value = 1.8
        elif before == 'per':
            value = 0.4
    elif word in ('储', '儲'):
        value = 0.0 if history.endswith('存') else 7.5
