"""An unchanged-prefix pulse, with a rough estimate of its token-dependent size.

The component is usually active only at a document's first token. It stays
active if that token repeats without any intervening different token. Short
tokens have smaller typical pulses than standalone, moderately common words;
space-prefixed words are weaker. These are coarse averages, not a token table.
"""
from wordfreq import zipf_frequency
import regex

READS = ()


def pulse(text):
    word = text.strip()
    if '\n' in text:
        return 1.5
    if not word:
        return 3.2
    if word == '0':
        return 0.0
    if word.isdigit():
        return 3.5
    if all(c == '#' for c in word):
        return 7.6
    if len(word) <= 2:
        if word.isascii():
            return 2.9
        if regex.search(r'\p{Script=Han}', word):
            return 5.1
        return 3.8
    # Wordfreq uses a logarithmic scale: larger means more common.
    frequency = (zipf_frequency(word.lower(), 'en')
                 if word.isascii() and word.isalpha() else 0.0)
    if text.startswith(' '):
        if frequency >= 5:
            return 2.8
        return 4.6 if len(word) <= 5 else 3.1
    return 7.2 if 2 < frequency <= 6 else 4.4


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        unchanged = True
    else:
        unchanged = carry[2] and carry[1] == token
    value = pulse(prefix.token_strings[-1]) if unchanged else 0.0
    return (doc, token, unchanged), value

"""A mixed short-expression signal, not a general sentiment score.

Negative pulses mark explanatory/evaluative phrases ('is why', 'good thing',
'for a reason'), 'have got', and expressions denying doubt or surprise.
Negated time/degree adverbs have positive pulses. Smaller rules cover some
import conventions, typography and character fragments. These rules leave
most of the component's small, token-specific variation unexplained.
Only a 160-byte suffix is kept, and it resets at document boundaries.
"""
import re
import unicodedata
import regex

READS = ()


def phrase_value(word, previous, words):
    if word == 'why':
        copula = previous in {'is', 'was', 'are', 'were', "'s", '’s', 'thats'}
        if copula or (previous == 'also' and any(
                w in {'is', "'s", '’s'} for w in words[-3:])):
            return -3.9
        if previous in {'and', 'how', 'explains', 'explain', 'explaining'}:
            return -0.63
        return -0.13
    if word in {'reason', 'reasons'}:
        if word == 'reasons':
            return -0.57
        return {'a': -3.0, 'this': -2.0, 'that': -2.0,
                'good': -1.65, 'very': -1.65, 'no': -1.1}.get(previous, -0.34)
    if word == 'thing':
        if previous in {'good', 'bad'}:
            return -3.85
        if previous in {'great', 'beautiful', 'wonderful', 'nice'}:
            return -1.35
        return -1.1 if previous == 'a' else -0.15
    if word == 'got':
        auxiliary = previous
        if previous in {'really', 'just', 'already'} and len(words) >= 2:
            auxiliary = words[-2]
