                "'ve": -1.38, '’ve': -1.38,
                "'s": -1.38, '’s': -1.38}.get(auxiliary, -0.05)
    if previous in {'no', 'little'}:
        return {'wonder': -4.8, 'secret': -2.8, 'surprise': -1.9,
                'question': -1.8, 'doubt': -0.39, 'reason': -1.1,
                'way': -0.29, 'evidence': -0.29, 'case': -0.29}.get(word, 0.0)
    if previous in {'good', 'great'} and word == 'question':
        return -2.8
    if previous in {'a', 'without'}:
        value = {'question': -0.5, 'wonder': -0.7,
                 'secret': -0.22, 'surprise': -0.34, 'doubt': -0.63}
