            return value[word]
    if previous in {'not', "'t", '’t'}:
        return {'yet': 0.94, 'quite': 0.78, 'really': 0.57}.get(word, 0.0)
    if previous == 'why' and word == 'not':
        return 0.9
    if previous == 'ne' and word == 'pas':
        return 1.05
    if previous == 'as' and word in {'if', 'though'}:
        return -0.64
    if previous == 'any' and word in {'way', 'evidence', 'case'}:
        return -0.29
    if previous == 'good' and word == 'job':
        return -0.43
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else b''
    new = prefix.token_bytes[-1]
    token = prefix.token_strings[-1]
    before = old.decode('utf-8', 'ignore')
