    if word in {'always', 'never', 'often', 'sometimes', 'usually', 'rarely'}:
        value += 0.13
    if word in {'maybe', 'perhaps', 'probably'}:
        value += 0.06
    if word == 'indeed':
        value += 0.7 if previous in {'is', 'was', 'are', 'were'} else 0.06
    if word == 'than':
        value -= 0.11
    if word in {'anything', 'everything', 'nothing', 'anywhere', 'everywhere'}:
        value -= 0.17
