programs.haiku:
"""Layer 1, MLP down-projection, component 3531.

What it does, in plain terms: it is a set-phrase detector. It goes strongly
negative on the word that closes a fixed phrase, and weakly positive on "yet" /
"quite" after a negation. The phrases it knows:

  * "That's why", "This is why", "and why" (weaker)  -> "why"
  * "for a reason", "for this reason", "good reason"  -> "reason"
  * "good thing", "bad thing"                         -> "thing"
  * "no question", "no wonder", "no secret", "no way" -> the noun after "no"
  * "good question"                                   -> "question"
  * "I've got", "has got" (have-got, not past "got")  -> "got"
  * "not yet", "not quite"                            -> "yet"/"quite" (positive)
  * "import React from 'react'"                       -> "react" (strong negative)

Everything else is predicted as 0. The values are rough averages measured on
training text. The component is sparse and context-dependent, so most positions
are 0 and a few are large.
"""

READS = ()

# The word before the trigger word, and the value the trigger gets.
WHY_FRAMES = {"that's": -4.5, "thats": -4.3, "is": -3.9, "was": -2.9, "and": -0.9}
REASON_FRAMES = {"a": -3.0, "this": -1.9, "that": -2.2, "good": -2.8, "no": -1.1}
THING_FRAMES = {"good": -3.7, "bad": -4.1}
NO_NOUNS = {"wonder", "question", "reason", "reasons", "secret", "way", "case",
            "evidence", "doubt", "surprise", "choice"}
GOT_FRAMES = {"has": -4.2, "have": -2.8, "had": -1.5, "'s": -1.7, "'ve": -1.5}
NEGATION = {"not", "n't", "t", "'t"}
REACT_FRAMES = ("'", '"')


def _word(s):
    return s.strip().lower().replace("’", "'")


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    docs = prefix.document_ids
    t = prefix.position
    cur = _word(tokens[t])
    prev = _word(tokens[t - 1]) if t >= 1 and docs[t - 1] == docs[t] else ""
    value = 0.0
    if cur == "why":
        value = WHY_FRAMES.get(prev, 0.0)
    elif cur in ("reason", "reasons"):
        value = REASON_FRAMES.get(prev, 0.0)
    elif cur == "thing":
        value = THING_FRAMES.get(prev, 0.0)
    elif cur == "question":
        value = -2.6 if prev in ("no", "good") else (-0.5 if prev == "a" else 0.0)
    elif cur in NO_NOUNS:
        value = -2.5 if prev == "no" else 0.0
    elif cur == "got":
        value = GOT_FRAMES.get(prev, 0.0)
    elif cur in ("yet", "quite"):
        value = 1.0 if prev in NEGATION else 0.0
    elif cur == "react":
        value = -7.0 if prev in REACT_FRAMES else 0.0
    return carry, float(value)

programs.sol:
"""A sparse, syntax-sensitive approximation, not a single semantic detector.

Paragraph/preformatted tags and C# documentation summaries excite it; several
HTML container/control tags suppress it. Repetition within a document weakens
these tag responses. Additional rules cover documentation labels, package
names, example addresses, forum metadata, and literal formatting marks.
Document-leading "12" and "Title:" have explicit responses, as do the
left-to-right mark and doubled middle dot. Unmarked letter p has a small
negative baseline; other unmatched tokens give zero. State resets by document.
"""
import math
import re

READS = ()

# Opening and closing tag responses, before repetition attenuation.
TAGS = {
    'p': (5.4, 4.3),
    'pre': (3.0, 2.7),
    'summary': (0.9, 0.7),
    'template': (2.2, 1.0),
    'ul': (0.8, 0.8),
    'button': (-4.9, -2.8),
    'textarea': (-3.6, -2.0),
    'title': (-3.7, -3.0),
    'details': (-2.2, -2.7),
    'body': (-2.2, -2.8),
    'head': (-1.7, -2.3),
    'html': (-1.4, -2.3),
    'form': (-1.6, -1.6),
    'input': (-1.3, -1.0),
    'selector': (-1.0, -1.0),
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, previous, position, counts = '', '', 0, {}
    else:
        _, recent, previous, position, counts = carry
    s = prefix.token_strings[-1]
    value = -0.17 if s == 'p' else 0.0
    closing = recent.endswith('</')
    if s in TAGS and (closing or recent.endswith('<')):
        stem = recent[:-2] if closing else recent[:-1]
        comment = bool(re.search(r'(\*|///)\s*$', stem))
        value = TAGS[s][int(closing)]
        if comment and s == 'p' and not closing:
            value = 12.0
        elif comment and s == 'summary':
            value = 3.9 if closing else 7.0
        elif comment and s == 'pre':
            value = 3.4 if closing else 4.5
        n = counts.get(s, 0)
        value *= 0.65 + 0.35 / math.sqrt(n + 1)
        counts[s] = n + 1
    elif s in ('<p', '<P') and recent[-1:] in ('\n', ' ', '>'):
        value = 6.5 if s == '<p' else 4.5
    elif recent.endswith('@'):
        value = {'description': 2.4, 'property': 1.0,
                 'param': -0.2}.get(s, 0.0)
    elif s == ' com' and previous in ('import', 'package', ' static'):
        value = {'import': 2.25, 'package': 3.0, ' static': 0.6}[previous]
    elif s == '.com':
        if recent.endswith('@example'):
            value = 5.1
        elif previous == 'github':
            value = -0.45
        else:
            value = 0.2
    elif s == 'udos' and recent.lower().endswith('k'):
        value = -3.2 if 'Followers:' in recent else 0.5
    elif s == 'test' and recent.endswith('#['):
        value = -1.5
    elif s == 'command' and recent.endswith('\\new'):
        value = 2.0
    elif s == 'anonymous' and recent.endswith('<'):
        value = 1.3
    elif s == '.Tasks' and recent.endswith('.Threading'):
        value = 3.2
    elif s.strip() == '\u200e':  # Unicode left-to-right mark
        value = 2.4
    elif s == '··':
        value = 0.95
    elif s.startswith('/>'):
        value = 1.5
    if position == 1:
        if recent == '1' and s == '2':
            value = 7.5
        elif recent == 'Title' and s == ':':
            value = -5.1
    return (doc, (recent + s)[-150:], s, position + 1, counts), value

programs.haiku:
"""Paragraph and summary tags inside code doc-comments, plus a few name pieces.

The component is a "doc-comment markup" feature. It fires most on the tag name of an
HTML-style tag opened or closed with "<" or "</":
- <p> (and </p>) is strongly positive, most inside a doc comment (a Javadoc line starting
  with "*", as in " * <p>"), and less in ordinary HTML;
- <summary> is strongly positive inside a C#-style "///" doc-comment line;
- <pre> is mildly positive; <button> is negative.
Smaller, separate responses: "com" as the root of a Java package name ("import com."),
".com" in a placeholder address ("email@example.com"), and the colon of a "Title:" line
that opens a scraped document (negative). Everything else is predicted as 0.
"""

READS = ()

DOC_TAG = {"p": 11.0, "summary": 6.0, "pre": 4.5}
HTML_TAG = {"p": 6.5, "pre": 2.4, "button": -1.5}


def in_doc_line(text_before):
    line = text_before.split("\n")[-1].lstrip(" \t")
    return line.startswith("*") or line.startswith("///")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    before = prefix.token_strings[-2] if len(prefix) > 1 else ""
    before2 = prefix.token_strings[-3] if len(prefix) > 2 else ""
    if before.endswith("<") or before.endswith("</"):
        name = token.strip()
        if in_doc_line(prefix.text_prefixes[-2]):
            return carry, float(DOC_TAG.get(name, 0.0))
        return carry, float(HTML_TAG.get(name, 0.0))
    if token == "<p":
        return carry, 6.0
    if token == " com" and before in ("import", "package"):
        return carry, 2.5
    if token == ".com":
        if before.endswith("@example"):
            return carry, 5.0
        if "github" in before.lower():
            return carry, -0.3
        return carry, 0.5
    if token == ":" and before == "Title" and before2 == "<|endoftext|>":
        return carry, -5.0
    return carry, 0.0

programs.sol:
"""Predict a pulse at a row/document start, not a sustained topic feature.

Opening code declarations and question words amplify it. Ordinary opening words
use case and English word frequency; punctuation, whitespace and scripts have
coarser averages. An uninterrupted run of the same opening word/digit keeps the
pulse. Heredoc EOF markers and an immediately following newline get smaller
pulses.
Other tokens get zero. Fine lexical differences and weaker string-opening
effects are deliberately omitted.
"""
from functools import lru_cache
import re
import regex
from wordfreq import zipf_frequency

READS = ()
ARTICLES = {'a', 'an', 'the'}
QUESTIONS = set('what how when where why which who whom whose'.split())
AUXILIARIES = set(
    'am is are was were be been being do does did have has had '
    'can could will would shall should may might must'.split()
)
DECLARATIONS = set(
    'def fn func fun function package int string float double char '
    'void long bool boolean String import class const let interface '
    'from use using namespace module type var public private static'.split()
)


@lru_cache(maxsize=8192)
def opening_value(token):
    word = token.strip()
    lower = word.lower()
    spaced = token != token.lstrip()
    if token == '<|endoftext|>':
        return 0.8  # Document separator, not opening content
    if token == '<|im_end|>':
        return 4.4  # End-of-message control marker
    if token.startswith('<|'):
        return 5.5
    if not word:
        if token == ' ' * len(token) and len(token) > 1:
            return 6.5
        return 0.0
    if word in DECLARATIONS:
        if word == 'def':  # Python function definition
            value = 60.9
        elif word == 'fn':  # Rust function definition
            value = 38.5
        elif word in {'package', 'int', 'string', 'function', 'func', 'fun'}:
            value = 25.0
        elif word in {'import', 'char', 'float', 'double'}:
            value = 20.0
        elif word in {'class', 'const', 'let', 'interface', 'void', 'long', 'bool'}:
            value = 18.5
        else:
            value = 12.8
        # Indented/space-prefixed keywords carry a weaker opening signal.
        if token.startswith('\t'):
            return min(20.0, value * 0.8)
        return value * 0.45 if spaced else value
    if not spaced and word in {'SELECT', 'select'}:
        return 23.5 if word.isupper() else 16.5  # SQL query opening
    if not spaced and (word == 'create' or word in {
        'CREATE', 'INSERT', 'UPDATE', 'DELETE', 'ALTER', 'DROP', 'SET'
    }):
        return 13.0  # SQL data/schema statement openings
    if word in {'print', 'printf', 'println', 'echo', 'console'}:
        return 11.0  # Console-output commands
    if word.isdecimal():
        return 3.8
    if lower in ARTICLES:
        return 8.2
    if lower in QUESTIONS:
        if word in {'What', 'How'}:
            return 15.0
        return 11.0 if word.istitle() else 7.5
    if lower in AUXILIARIES and word.istitle():
        return 8.9
    if word.isascii() and word.isalpha():
        frequency = max(0.0, zipf_frequency(lower, 'en') - 4.5)
        if word.istitle() and len(word) > 1:
            return 4.5 + 0.9 * frequency
        if word.isupper():
            return 4.0 + frequency
        return 4.6 + 0.55 * frequency
    if regex.search(r'\p{Script=Han}', word):
        return 3.6
    if word.isalpha():
        return 4.8
    if '\ufffd' in word:
        return 2.0
    if word.replace('_', '').isalpha() or (
        word.startswith('.') and word[1:].isalpha()
    ):
        return 4.8
    if word.startswith('#'):
        return 6.7
    if '\n' in token or '\r' in token:
        return 1.2
    if word.startswith('/*') or word.startswith('//'):
        return 4.5
    if word in {',', ';', ')', ']', '}'}:
        return 4.8
    if word == '.':
        return 3.2 if not spaced else 0.3
    if word[0] in '([{"\'`【:|-\\_':
        return 0.2
    return 2.8


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token_id = prefix.token_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        value = opening_value(token)
        repeat = token.strip().isalnum()
        return (doc, token_id, repeat, value, token[-48:], 0.0), value

    _, first_id, repeat, initial_value, tail, pending = carry
    repeat = repeat and token_id == first_id
    value = initial_value if repeat else 0.0
    if pending and '\n' in token:
        value = pending  # Newline beginning a multiline shell/PHP string
    following = 0.0
    if token == 'EOF':
        marker = re.search(r'<<-?\s*([\'\"]?)$', tail)
        if marker:
            quoted = bool(marker.group(1))
            value = 2.8 if quoted else 3.2
            following = 1.1 if quoted else 1.9
    return (doc, first_id, repeat, initial_value,
            (tail + token)[-48:], following), value

"""Approximate the component's doubled-C fragment response.

Short pieces containing CC, a C continued by C, and the immediate
continuation of a piece ending in CC receive positive values. Capital
initialisms and very short continuations are stronger. Frequent English
or Italian concatenations are downweighted at a C-C boundary. Small rules
also recognize ch-c and Cyrillic consonant clusters. Everything else is
zero, leaving unrelated negative and document-start responses unmodeled.
"""
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=8192)
def familiar_word(word):
    return max(zipf_frequency(word, lang) for lang in ('en', 'it')) >= 4.2


def predict(token, previous):
    s = token.strip()
    low = s.lower()
    p = previous.lower()
    joined = bool(previous[-1:].isalpha() and token[:1].isalpha())
    value = 0.0

    if 'cc' in low and len(s) <= 5:
        if s.isupper():
            value = 4.1 if joined else 2.0
            if s == 'CC' and not joined:
                value = 1.1
        else:
            value = 2.4 if joined else 0.9
            if low == 'cc' and joined:
                value = 3.9
            # Mc is a surname prefix, not two identically cased letters.
            if s.startswith('Mc'):
                value = 0.2
        if len(s) == 5:
            value *= 0.7

    if joined and p.endswith(('c', 'ch')) and low.startswith('c'):
        if p.endswith('ch'):
            value = 2.5 if len(s) == 1 else 0.6
            if len(previous.strip()) > 3 or len(s) > 3:
                value = 0.0
        elif len(s) <= 2:
            value = 5.0
        elif len(s) <= 4:
            value = 3.1
        else:
            value = 1.1
        if s[:1].isupper() and not s.isupper():
            value += 1.2
        if previous.endswith('CC'):
            value = 6.8
        if len(s) >= 3 and familiar_word(previous.strip() + token):
            value *= 0.2
    elif joined and p.endswith('cc'):
        if len(s) == 1:
            value = 5.3 if s.isupper() else 2.2
            if previous == ' CC':
                value = 1.4
        elif len(s) == 2:
            value = 1.0
        elif len(s) == 3:
            value = 0.8
        else:
            value = 0.3

    # Related consonant clusters in Cyrillic spelling.
    if joined and p.endswith('к'):
        if low.startswith('ц'):
            value = 3.4 if len(s) == 1 else 1.1
        elif low.startswith('к'):
            value = 1.3
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    return (doc, token), predict(token, previous)

"""Negative responses to typography that interrupts words or prose.

Dictionary frequencies distinguish common complete words from unfinished word
beginnings. Hyphens on the latter receive the largest negative predictions.
Line-end and soft hyphens, and literal backslash-newlines in prose, are further
printing artifacts. A short echo covers the token immediately after a break.
Only a short text window and counts within the current document are retained.
"""
import math
import re
from collections import defaultdict
from wordfreq import get_frequency_dict

READS = ()
LANGUAGES = ('en', 'fr', 'de', 'es', 'it', 'ru')
WORDS = {}
BEGINNINGS = {}
for language in LANGUAGES:
    WORDS[language] = get_frequency_dict(language, 'small')
    beginnings = defaultdict(float)
    for word, frequency in WORDS[language].items():
        if word.isalpha():
            for n in range(2, min(len(word), 20)):
                beginnings[word[:n]] += frequency
    BEGINNINGS[language] = beginnings


def language_of(text):
    words = re.findall(r'[^\W\d_]{2,}', text.lower())[:-1][-20:]
    if len(words) < 3:
        return 'en'
    return max(LANGUAGES, key=lambda lang: sum(
        math.log10(WORDS[lang].get(w, 0) + 1e-7) for w in words))


def frequencies(word, language):
    word = word.lower()
    complete = math.log10(WORDS[language].get(word, 0) + 1e-9) + 9
    beginning = math.log10(BEGINNINGS[language].get(word, 0) + 1e-9) + 9
    return complete, beginning


def hyphen_value(token, previous, text, split_count):
    match = re.search(r'([^\W\d_]+)\Z', text)
    if not match:
        return 0.0
    word = match.group(1)
    prose = sum(c.isalpha() or c == ' ' for c in text) / max(1, len(text))
    code = sum(c in '_=/<>{}[]`\\' for c in text) / max(1, len(text))
    # A word embedded in a path or a numbered identifier is not broken prose.
    chunk = re.split(r'\s', text)[-1]
    if any(c.isdigit() or c in '/_' for c in chunk):
        return 0.0
    if token == '\xad':
        return -4.5
    if token == '-\n' and len(word) > 1:
        return -3.7 if prose > 0.8 and code < 0.08 else 0.0
    suffix = token[1:].strip()
    lang = language_of(text)
    complete, beginning = frequencies(word, lang)
    joined_complete, joined_beginning = frequencies(word + suffix, lang)
    suffix_complete, _ = frequencies(suffix, lang)
    prefix_bias = beginning - complete
    joined_bias = joined_beginning - joined_complete
    if joined_bias <= 0.68:
        return -0.14 if not suffix and len(word) > 1 else 0.0
    # Strong evidence that the preceding letters are an unfinished word.
    if prefix_bias > 4.7:
        if word[0].isupper():
            return -0.15 if len(word) <= 3 else -2.2
        return -0.3 if code > 0.034 else -7.4
    if suffix_complete > 0:
        return 0.0
    # Weaker fragments become more convincing in repeatedly broken-up prose.
    if split_count > 1:
        if prose > 0.96:
            return -5.8
        return -1.9 if complete <= 3.7 else -4.3
    if prose > 0.96:
        return 0.0 if word.isupper() else -2.0
    return -1.0 if previous.startswith(' ') else -0.2


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', '', 0, 0.0)
    _, text, previous, split_count, echo = carry
    token = prefix.token_strings[-1]
    if previous == '-' and token[:1].isspace():
        split_count += 1
    if token.startswith('-') or token == '\xad':
        value = hyphen_value(token, previous, text, split_count)
        new_echo = value * 0.3 if value < -0.4 else 0.0
    else:
        value = echo
        new_echo = 0.0
        kind = (0 if token == '\\n' else
                1 if token.endswith('\\') and len(token) <= 4 else
                2 if previous.endswith('\\') and token.startswith('n') else -1)
        if kind >= 0 and not re.search(r'[_=/<>{}\[\]`]', text):
            words = re.findall('[a-z]{2,}', text.lower())
            frequent = bool(words) and frequencies(words[-1], 'en')[0] > 5.7
            if frequent:
                value -= 0.6 if '\\' in text else 0.03
            else:
                value -= 0.37 if kind == 2 else 0.18
    if '\n' in token and '-' in token:
        split_count += 1
    return (document, (text + token)[-150:], token, split_count, new_echo), float(value)

"""Surface-form approximation to a multilingual tong / thống / 統 detector.

The strongest rules recognize the isolated morpheme, including a Han character
finished across byte tokens. Compounds are weaker. Split Latin syllables use
only the previous token. Japanese t-class verb inflections have a negative rule.
A few punctuation/layout responses are separate rules;
this does not attempt to predict the component's many small lexical responses.
"""
import codecs
from functools import lru_cache
import unicodedata
import regex
import jmdict
from opencc import OpenCC

READS = ()
SIMPLIFY = OpenCC('t2s')
CHINESE_COMPOUNDS = {
    '统一': 5.3,  # unify
    '统领': 5.3,  # lead
    '统统': 3.1,  # all
    '统计': 1.5,  # statistics
    '总统': 1.9,  # president
    '系统': 0.3,  # system
}


@lru_cache(maxsize=8192)
def unaccent(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


@lru_cache(maxsize=4096)
def tsu_verb_stem(char):
    """A Han stem that can take the Japanese godan-verb ending -tsu."""
    if not regex.fullmatch(r'\p{Script=Han}', char):
        return False
    return any(r.endswith('つ') for r in jmdict.readings(char + 'つ'))


@lru_cache(maxsize=65536)
def morpheme(text, split):
    word = text.strip()
    if word in {'統', '统'}:
        return 14.0 if split else 9.0
    if split and word in {'総', '繫'}:
        return 1.3
    if split and word == '繋':
        return 3.0
    if word == '通':
        return 1.8
    # Japanese object particle followed by the "pass through" morpheme.
    if word == 'を通':
        return 3.0
    if word == '통':
        return 7.0 if text.startswith(' ') else 5.4
    if word.lower() == 'thống':
        return 9.0
    if word.lower() == 'thông':
        return 4.0
    if word.lower() == 'tổng':
        return 2.0
    if word.lower() == 'tong':
        return 4.9
    # Normalize traditional/simplified spelling for the compound rules.
    simple = SIMPLIFY.convert(word)
    if simple in {'传统', '的传统'}:  # tradition
        return 1.6 if '傳' in word else 0.7
    return CHINESE_COMPOUNDS.get(simple, 0.0)


def predict(text, previous, split, position):
    value = morpheme(text, split)
    p = unaccent(previous).rstrip()
    s = unaccent(text)
    # A separately tokenized ong is usually negative, except after t/th.
    if s in {'ong', 'onga'}:
        value = -0.55
        if p.endswith(('t', 'th', 'thu')):
            value = 6.5 if p.strip() in {'t', 'th', '-t'} else 3.5
    elif s in {'am', 'om', 'oms'} and p.endswith('th'):
        value = 2.0 if s == 'am' else 1.0
        if not previous.startswith(' '):
            value *= 0.6
    # The same roots are weaker inside tradition/bloodline and traffic.
    if text in {'統', '统'} and previous.endswith(('伝', '傳', '传', '血')):
        value = 5.0
    if text == '통' and previous.endswith('교'):
        value = 2.2
    # Thai 'both/all', when its final consonant is split off.
    if text == 'ง' and previous.endswith('ทั้'):
        value = 2.5
    # The second character of the split word "unify" remains strongly active.
    if previous.strip() in {'統', '统'} and text == '一':
        value = 6.0
    if previous.strip() in {'統', '统'} and text in {'計', '计'}:
        value = 1.5
    if previous.strip() == '통' and text == '일':
        value = 4.3
    # Negative Japanese inflections of t-class verb stems.
    if text in {'た', 'て'} and previous and tsu_verb_stem(previous[-1]):
        value = -1.5 if text == 'た' else -0.5
    if text == '··':
        value = -1.06
    if position == 0:
        if text == '<!':
            value = 8.6
        elif text == '//\n':
            value = 4.25
        elif text.isspace() and ('\n' in text or '\t' in text):
            value = -0.6 if '\n' in text else -1.1
    if position == 1 and previous == 'Title' and text == ':':
        value = -7.49
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '', 0)
    _, pending, previous, position = carry
    data = pending + prefix.token_bytes[-1]
    text, consumed = codecs.utf_8_decode(data, 'replace', False)
    value = predict(text, previous, bool(pending), position)
    return (doc, data[consumed:], text, position + 1), float(value)

"""Mostly a document-onset pulse, with size set by token shape.

Words receive a large pulse; digits, punctuation and whitespace receive
smaller ones. Case, length, and a leading space refine Latin word pulses.
The pulse persists through exact repetitions of the initial token. Away
from onset, the only predicted response is to a single space immediately
following another indentation token. Exact word-specific amplitudes and
smaller contextual responses are deliberately not represented.
"""
import math
import regex

READS = ()


def onset_pulse(text):
    word = text.strip()
    if text.startswith('<|'):
        return 15.1 if text == '<|im_start|>' else 10.6
    if not word:
        if '\n' in text:
            return 0.65 if text.count('\n') > 1 else 3.75
        return 0.25 if text == ' ' else 7.6
    if word.isdigit():
        return 0.08 if set(word) == {'0'} else 4.3
    if regex.search(r'\p{Script=Latin}', word):
        if word.startswith('#'):
            return 6.7
        if len(word) == 1:
            return 9.1
        if not word[0].isalpha():
            base = 5.9
        else:
            base = 8.2 if word[0].isupper() else 6.3
        return (base + 2.27 * math.log1p(len(word))
                + 1.15 * text.startswith(' '))
    if any(c.isalpha() for c in word):
        return 9.9
    if '\ufffd' in text:
        return 6.5
    if set(word) <= set('.,:，。：-–—'):
        return 0.45
    return 3.6


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        initial, onset, previous = token, True, ''
    else:
        _, initial, onset, previous = carry
        onset = onset and token == initial
    if onset:
        value = onset_pulse(text)
    elif text == ' ' and previous and not previous.strip(' \t'):
        value = 1.35
    else:
        value = 0.0
    return (document, initial, onset, text), value

programs.haiku:
"""Component layers.1.mlp.down_proj:3537 (a "document-start" feature).

What it does, in plain terms:
  * At the first token of every document (the first token of a row, or the first
    token after a document boundary) it is strongly positive. How strong depends on
    what that token is: a special marker such as <|im_start|> is highest (~15);
    a word of four or more letters (with or without a leading space) is high (~12);
    a shorter word fragment is medium (~9.5); a number, punctuation mark or other
    symbol is low (~3.5); a bare newline or tab-run start is ~5; a lone space is ~0.
    Because it is the first token, nothing before it is available: the value depends
    on the token alone.
  * Later in a document it is almost always zero. Two exceptions:
    - a run of middle dots "·" (as in dotted leaders) fires a steady ~5.2;
    - a single space that follows another whitespace-only token (indentation
      continuing, e.g. the space after a run of spaces) fires ~1.3.

The program needs no state between positions: it reads only the newest token and
whether the document id has just changed.
"""

READS = ()

LEADER_DOT = "·"


def first_token_value(s):
    """Activation at a document's first token, from the token's text alone."""
    core = s.strip(" ")
    if s.startswith("<|") and s.endswith("|>"):
        return 15.0  # special markers such as <|im_start|>
    if core[:1].isalpha():
        return 12.0 if len(core) >= 4 else 9.5  # words; longer words higher
    if core == "" and s != " ":
        return 5.0  # newline / tab / multi-space token
    return 3.5  # digits, punctuation, symbols


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    t = prefix.position
    starts_document = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if starts_document:
        if s == " ":
            return carry, 0.25  # a lone space at document start is near zero
        return carry, first_token_value(s)
    if s and set(s) == {LEADER_DOT}:
        return carry, 5.2  # run of middle dots
    previous = prefix.token_strings[-2]
    if s == " " and previous and set(previous) == {" "}:
        return carry, 1.3  # space continuing an indentation run
    return carry, 0.0

programs.sol:
"""Approximate the response to fractured English spellings, plus openings and 30.

In English-looking text, short tokens that are rare words but prefixes of
common words get a small positive response. So do continuations that turn a
common prefix into a rare word. These are conservative proxies for the
stronger, context-sensitive responses seen in typos, OCR and older spelling.
Separate rules cover isolated nasal-a, opening delimiters and numerals.
"""
import re
from functools import lru_cache
from wordfreq import top_n_list, zipf_frequency

READS = ()
COMMON_PREFIX = {}
for word in top_n_list('en', 100000):
    if word.isascii() and word.isalpha():
        frequency = zipf_frequency(word, 'en')
        for length in range(1, len(word) + 1):
            start = word[:length]
            COMMON_PREFIX[start] = max(COMMON_PREFIX.get(start, 0), frequency)


@lru_cache(maxsize=100000)
def frequency(word):
    return zipf_frequency(word, 'en')


def opening(s):
    word = s.strip()
    if s == '**':
        return 1.8
    if s.startswith(('/*', '"""', "'''")):
        return 0.9
    if s.startswith(('#include', '#pragma')):
        return 0.7
    if word in {'•', '*'}:
        return 0.65
    if s == '<|endoftext|>':
        return 1.5
    if word.isdigit():
        return 0.07
    if word.isascii() and word.isalpha():
        if word.istitle() and len(word) >= 3:
            return 0.25
        if len(word) >= 5:
            return 0.15
        if word.islower() and len(word) <= 2:
            return -0.10
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', 0.0, '', '')
    _, position, old_word, english_frequency, previous, before = carry
    s = prefix.token_strings[-1]
    token = s.strip()
    starts_word = s[:1].isspace() or not old_word
    continues = not starts_word and bool(re.match('[A-Za-z]', s))
    joined = (old_word if continues else '') + token
    tail = re.search('[A-Za-z]+$', joined)
    word = tail.group()[-40:] if tail else ''
    token_frequency = frequency(token.lower()) if token.isalpha() else 0
    word_frequency = frequency(word.lower()) if word else 0
    surplus = COMMON_PREFIX.get(token.lower(), 0) - token_frequency
    drop = (COMMON_PREFIX.get(old_word.lower(), 0)
            - COMMON_PREFIX.get(word.lower(), 0))

    value = 0.0
    if position == 0:
        value = opening(s)
    elif position == 1 and previous == '1' and s == '2':
        value = 1.45
    elif previous == '3' and s == '0':
        value = 0.10 if before.isdigit() else 0.27
        if before == ':':
            value = 0.47
    else:
        letters = token.isascii() and token.isalpha() and token.islower()
        short_start = letters and len(token) <= 4 and s[:1].isspace()
        if short_start and english_frequency > 4.7:
            if surplus > 1.5:
                value += 0.055
            if surplus > 3:
                value += 0.04
        if (letters and continues and english_frequency > 4.7
                and drop > 3 and word_frequency < 4):
            value += 0.025
        if token == 'ã':
            value = 0.8

    if starts_word:
        english_frequency = 0.9 * english_frequency + 0.1 * token_frequency
    carry = (doc, position + 1, word, english_frequency, s, previous)
    return carry, value

