import codecs
import opencc

READS = ()
SIMPLIFY = opencc.OpenCC('t2s')
UTF8 = codecs.getincrementaldecoder('utf-8')
INSTITUTIONS = (
    '协会', '委员会', '常委会', '管委会', '证监会',
    '议会', '国会', '工会', '联合会', '代表大会',
)


def token_value(raw):
    original = raw.strip()
    text = SIMPLIFY.convert(original)
    traditional = '會' in original
    if text == '会':
        return 5.15 + 0.4 * traditional
    if text == '不会':
        return 6.8 + 0.3 * traditional
    if '会' in text:
        if text.endswith(('社会', '机会')):
            return 0.7
        if text.endswith(INSTITUTIONS):
            return 1.7
        if text.endswith('会'):
            return 3.8 + 0.7 * traditional
        return 1.5 / max(1, len(text) - 1)
    if text == '회':
        return 5.7 if raw.startswith(' ') else 2.0
    if text.startswith('회'):
        return 1.5
    if text.lower() == 'hội':
        return 2.0
    if text == '汇':
        return 2.5
    if text in ('回', '絵'):
        return 0.55 if text == '回' else 1.0
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        pending, previous = b'', ''
    else:
        _, pending, previous = carry
    decoder = UTF8('ignore')
    decoder.setstate((pending, 0))
    raw = decoder.decode(prefix.token_bytes[-1])
    pending = decoder.getstate()[0]
    value = token_value(raw)

    # Romanized hui/hoi may be split just after their initial h.
    fragment, before = raw.strip().lower(), previous.strip().lower()
    if fragment == 'ui' and before.endswith('h'):
        value = 4.2 if before == 'h' else 1.3
    elif fragment == 'oi' and before.endswith('h'):
        value = 1.6
    return (document, pending, raw), value

