            value = -3.2
    elif RECIPIENT.fullmatch(word):
        value = -6.0
    elif word in ('给了', '給了'):
        value = -2.3
    elif word in ('供给', '供給'):
        value = -3.4
    elif word in ('会给', '會給'):
        value = -8.0
    elif word in ('给予', '給予', '给出'):
        value = -1.2
    elif word.lower() == 'cho':
