        if boundary and VIETNAMESE.search(tail.decode('utf-8', 'ignore')):
            value = -5.4
    elif word == 'cấp':
        value = -3.8
    elif word == 'ให':
        value = -1.65
    elif word == '้' and previous.endswith('ให'):
        value = -2.6
    elif word == '급':
        value = -4.0

    if position == 0 and word.startswith(('给', '給')):
        value *= 0.5

    new_tail = (tail + raw)[-160:]
