    'unexpected': 1.85, 'sudden': 1.2, 'immediate': 1.7,
    'certainty': 1.6, 'frequency': 0.75, 'aspect': 0.7,
    'scope': 0.5, 'degree': 0.15, 'emphasis': 1.0,
    'modal': 0.2, 'manner': 0.65, 'connective': 0.375,
    'sudden_short': 4.0, 'vietnamese': 0.9,
    'vietnamese_all': 2.75, 'particle': -0.15,
    'compound': 0.25,
