HAN = regex.compile(r'\p{Script=Han}+$')
PARTICLES = set('了着过吗呢吧')
VIETNAMESE = set('lại cũng vẫn thường thì'.split())

@lru_cache(maxsize=16384)
def normalized(text):
    return SIMPLIFY.convert(text.strip()) if HAN.fullmatch(text.strip()) else text.strip()

@lru_cache(maxsize=16384)
def word_group(word):
    if word in {'忽', '竟'}:
        return 'sudden_short'
    if word in PARTICLES:
        return 'particle'
    return GROUP.get(word)

@lru_cache(maxsize=16384)
def dictionary_word(word):
    return bool(cedict.glosses(word))

def classify(text, previous):
    word = normalized(text)
    if word and set(word) <= {'·'} and len(word) > 1:
        return 'dots'
    if word == 'đều':
