    group = word_group(word)
    # Recognize words split across tokens, e.g. 照 + 旧 ("as before").
    for n in (3, 2, 1):
        if len(previous) >= n:
            joined = previous[-n:] + word
            complete = word_group(joined)
            if complete and len(joined) > 1:
                return complete
    # A monosyllabic adverb may instead finish a non-adverb word,
    # e.g. 全 in 安全 ("safe"), or 就 in 成就 ("achievement").
    if group and group != 'particle' and len(word) == 1 and previous:
