    return -0.275 if text.isascii() and text.isalpha() else -0.16

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, last = 0, '', ''
    else:
        _, position, previous, last = carry
    text = prefix.token_strings[-1]
    # A byte token may finish a Han character begun by an earlier token.
    if '\ufffd' in text:
        count = min(4, position + 1)
