        value = 4.58
    previous = (previous + word)[-4:] if HAN.fullmatch(word) else ''
    return (doc, position + 1, previous, text), value

"""A mostly negative detector of 'by' and related letter sequences.

The strongest everyday trigger is the English word 'by'.  Its level depends
on the preceding word: 'required by' and 'limited by' are strong negative
constructions; 'followed by' is positive; division/multiplication are mild.
Otherwise a few broad WordNet verb classes adjust a negative baseline.
Joined by-suffixes, b/y split across tokens, and b/j spellings also respond.
Only a short same-document text tail is retained.  Other activity is omitted.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
BY_COMPOUNDS = {'nearby', 'thereby', 'hereby', 'whereby', 'standby', 'goodbye'}


@lru_cache(maxsize=2048)
def english_by(word):
    # Recognizable constructions with particularly different responses.
    if word == 'required':
        return -6.4
    if word == 'limited':
        return -4.8
    if word == 'followed':
        return 0.6
    if set(wordnet.base_forms(word, 'verb')) & {'divide', 'multiply'}:
        return -0.9
    categories = wordnet.categories(word, 'verb')
    value = -1.9
    value += 0.7 * ('verb.creation' in categories)
    value -= 0.7 * ('verb.emotion' in categories)
    value -= 0.33 * ('verb.contact' in categories)
    value += 0.35 * wordnet.is_a(word, 'communicate')
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    stripped = token.strip()
    low = stripped.lower()
    previous = tail.rstrip()
    value = 0.0
    if low == 'by':
        match = re.search(r'[^\W\d_]+$', previous)
        last_word = match.group() if match else ''
        if not tail:
            value = {'by': 0.24, 'By': -2.12, 'BY': -3.4}.get(token, -0.6)
        elif token in (' by', ' By'):
            value = english_by(last_word.lower())
            if previous and not previous[-1].isalnum():
                value -= 0.36
        elif stripped == 'BY':
            value = -3.4
        elif stripped == 'By':
            value = -2.9 if token == 'By' and tail[-1:].isalpha() else -2.2
        elif token == 'by' and tail[-1:].isalpha():
            value = -4.7 if last_word[:1].isupper() else -2.9
        else:
            value = -1.8
    elif re.fullmatch('bi?j', low):
        value = -2.8
    elif low in BY_COMPOUNDS:
        value = -1.9
    elif token in ('-by', '_by', '/by', '(by'):
        value = -2.3
    elif not token.startswith(' ') and low.endswith('by'):
        value = -3.5
    elif not token.startswith(' ') and low.endswith('bye'):
        value = -4.4
    elif token.lower() == 'bury':
        value = -3.7
    elif token.lower() == 'berry':
        value = -1.1
    elif tail[-1:].lower() == 'b':
        if token.isascii() and token.lower().startswith('y') and len(token) <= 3:
            value = -10.0 if token == 'Y' and tail[-1:] == 'B' else -6.0
        elif token in ('j', 'J', 'ij'):
            value = -3.5
    return (doc, (tail + token)[-96:]), value

