"""A document-opening pulse, calibrated by the opening token's kind.

Emit the pulse at the start of each document and throughout an uninterrupted
repetition of its first token. Estimate its height using whitespace, script,
case, punctuation, and a few grammatical classes. Zero and the package-header
keyword receive particularly large pulses. Predict zero after the opening run;
small contextual activations and token-specific differences are not modeled.
"""
import unicodedata
import regex

READS = ()
PRONOUNS = set(
    'i you he she it we they me him her us them this these those'.split()
)
SPATIAL_PREPOSITIONS = set(
    'in on at from into onto out over under within between among'.split()
)


def opening_pulse(text):
    word = text.strip()
    lower = word.lower()
    spaced = text.startswith(' ')
    if text.startswith('<|'):
        return 6.5
    if not word:
        if '\t' in text:
            return 4.8
        if '\n' in text or '\r' in text:
            return 3.8 if len(text) == 1 else 2.8
        return 0.2 if len(text) == 1 else 1.6
    if word.isdecimal():
        return 13.3 if int(word) == 0 else 4.0
    if word == 'package':
        return 13.6
    if word in {'import', 'export', 'using', 'require', 'module', 'namespace'}:
        return 8.4
    if word.startswith(('<?', '#!')):
        return 7.1
    if word.startswith(('/*', '//', '#')):
        return 6.0
    if all(unicodedata.category(c)[0] in 'PS' for c in word):
        if all(c in '()[]{}' for c in word):
            return 2.9
        if all(c in '.，。,;:!?…' for c in word):
            return 3.0
        return 4.0
    if not word.isascii():
        if regex.search(r'\p{Script=Han}', word):
            return 4.4
        if regex.search(r'\p{Script=Cyrillic}', word):
            return 6.4
        return 4.8
    if lower == 'the':
        return 3.3 if spaced else 4.1
    if lower in {'a', 'an'}:
        return 6.1
    if lower in PRONOUNS:
        return 4.4 if spaced else 7.0
    if lower in SPATIAL_PREPOSITIONS:
        return 3.7 if spaced else 5.8
    if lower in {'of', 'for', 'with', 'by', 'as', 'about', 'without'}:
        return 5.6
    if lower == 'to':
        return 6.9
    if lower in {'and', 'or', 'but', 'if', 'that', 'than', 'because', 'while'}:
        return 4.1
    if lower in {'be', 'is', 'am', 'are', 'was', 'were', 'been', 'being'}:
        return 6.4
    if len(word) == 1 and word.isalpha():
        return 5.2 if word.isupper() else 4.2
    if not word.isalpha():
        return 5.4
    if spaced:
        return 4.6
    if word.isupper():
        return 6.2
    return 7.5 if word[0].isupper() else 5.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, opening_pulse(prefix.token_strings[-1]))
    elif token != carry[1]:
        carry = (doc, carry[1], 0.0)
    return carry, carry[2]

"""A detector for separators in structured names.

Double colons are strong after lower-case namespace names, but weak after
class names, primitive types, and method-reference receivers. URLs and
repository-name double underscores give smaller responses. Single colons
mainly respond to diagnostics, TeX labels and XML namespace prefixes.

There are also tokenization-sensitive responses to split Unicode prefixes:
Greek Extended, Hebrew marks, Hangul syllables, Sinhala virama, and
Latin-1 introducers near Thai script or C1 controls. Unlisted tokens
predict zero.
"""
import regex as re

READS = ()
LOG_LABELS = {'error', 'warning', 'warn', 'note', 'panic', 'fatal', 'help'}
SCALAR_TYPES = {'bool', 'char', 'str', 'string', 'usize', 'isize'}


def scope_value(tail, word):
    if tail.endswith('.py'):
        return 0.5
    if re.search(r'\.[\w-]*-[\w-]+$', tail):  # CSS pseudo-element
        return 2.5
    if re.search(r'\.[A-Za-z_]\w*$|\.\.\s+[\w-]+$', tail):
        return 0.3  # Java method reference or reStructuredText directive
    if word in {'static', 'parent'}:
        return 0.2  # PHP class dispatch, not a namespace
    if not word.islower():
        return -0.15 if word else 0.0
    if word in SCALAR_TYPES or word.endswith(('_type', '_t')):
        return 1.8
    if any(c.isdigit() for c in word):
        return 3.8
    value = 8.0
    if word == 'std':
        value = 6.5
    elif word == 'crate':
        value = 11.0
    elif word == 'self':
        value = 0.2 if '$' in tail else 4.5
    if re.search(r'(?:\buse|\\nuse)\s+[\w:]*$', tail):
        value = min(12.5, value + 3.5)
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else b''
    tail = history.decode('utf-8', errors='ignore')
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    word = ''
    if token in (':', '__', '::', '::{', '://'):
        match = re.search(r'[A-Za-z_][A-Za-z_0-9]*$', tail)
        word = match.group() if match else ''
    value = 0.0
    if token in ('::', '::{'):
        value = scope_value(tail, word)
        if token == '::{':
            value *= 0.6
    elif raw == b'\xc2':
        # Unmerged Latin-1 introducer: strong near Thai-script text.
        value = 7.7 if re.search(r'\p{Script=Thai}', tail[-30:]) else 0.5
    elif raw == b'\xc2\x80\xc2':
        value = 5.3  # C1 control plus another Latin-1 introducer
    elif raw == b'\xd6':
        value = 2.9  # Introducer for Hebrew vowel/cantillation marks
    elif raw in (b'\xbc', b'\x86', b'\x8a') and tail:
        previous = prefix.token_bytes[-2]
        if raw == b'\xbc' and previous.endswith(b'\xe1'):
            value = 4.6  # Greek Extended prefix (U+1F00 to U+1F3F)
        elif raw == b'\x86' and previous.endswith(b'\xeb'):
            value = 8.4  # Split Hangul prefix near the syllable 노
        elif raw == b'\x8a' and previous.endswith(b'\xe0\xb7'):
            value = -8.3  # Sinhala virama
    elif token == '··':
        value = -1.7
    elif token == '__':
        if word and word[0].islower() and not tail.endswith('.' + word):
            value = 1.45
    elif token == '://':
        value = 2.0 if word == 'http' else 1.2 if word == 'https' else 0.5
    elif token == ':':
        value = -0.06
        if word.lower() in LOG_LABELS:
            value = 2.2 if word.islower() else 0.0
        elif re.search(r'\\(?:label|ref|eqref|autoref)\{[^{}]*$', tail):
            value = 2.5
        elif re.search(r'</?[a-z][\w-]*$', tail) or word == 'xmlns':
            value = 5.0
        elif word in {'node', 'mailto', 'urn', 'doi'}:
            value = 2.0  # URI scheme or persistent-identifier prefix
        elif re.search(r'[a-z]+-[a-z]+$', tail):
            value = 1.4  # Hyphenated property name, e.g. text-align
        elif re.search(r':(?:arg|param|type)\s+[a-z_]+$', tail):
            value = 0.8  # Sphinx documentation field
        elif word and word.islower():
            value = 0.15
    # Keep bytes so split characters are reassembled in the next context.
    return (doc, (history + raw)[-240:]), value

"""A coarse lexical and formatting approximation, not a token lookup table.

After the document start, Han-only tokens get a baseline determined by
character count and CC-CEDICT membership. Single characters are slightly
positive. Out-of-dictionary tokens are negative, especially tokens with
four or more characters. Dictionary words of three or more characters
also get small negative estimates.

Document starts use a separate baseline. An opening ``Title:`` field is
special: ``Title`` is negative and its colon is strongly positive. Other
non-Han tokens get a near-zero value. Word-specific extremes are not
modeled.
"""
from functools import lru_cache

import cedict
import regex

READS = ()


@lru_cache(maxsize=8192)
def han_value(s):
    """Long tokens outside the Chinese dictionary tend to be more negative."""
    n = len(s)
    if n == 1:
        return 0.023
    known = bool(cedict.glosses(s))
    if n == 2:
        return 0.005 if known else -0.14
    if n == 3:
        return -0.035 if known else -0.113
    return -0.16 if known else -0.41


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, first = 0, s
    else:
        position, first = carry[1] + 1, carry[2]
    state = (doc, position, first)
