FUNCTION_WORDS = set('''a an the of in on at to for with into as by about over
under and or but so than if while can could will would should may might must
have has had do does did not'''.split())
BE = {'is', 'are', 'was', 'were', 'be', 'been', 'being'}
IMPORT_WORDS = {'from', 'import', 'require'}
CONTRACTIONS = {'s', 't', 'd', 're', 've', 'll', 'm'}
SHELL_COMMANDS = {'sed', 'echo', 'printf'}
SQL_STRING_KEYWORDS = {'comment', 'sqlstate'}


def spaced_quote(previous, recent):
    """Local punctuation and word classes distinguish prose from string syntax."""
    # Shell options and mapping/here-document operators introduce strings.
    if re.search(r'(?:^|\s)-{1,2}[A-Za-z][\w-]*$', recent):
        return -3.2 if re.search(r'\bsed\b', recent[-80:]) else -2.0
    if recent.rstrip().endswith('<<'):
