    p = -0.42 + 1.12*c.isalpha() + 3.88*c.isdigit() - 0.31*c.isspace()
    p += -0.72*(c == '=') - 0.36*(c == ':')
    p += 1.02*(c in ')]}') + 0.79*(c == '.')
    p += 0.32*(word in FUNCTION_WORDS) + 0.50*(word in BE)
    p -= 2.12*(word in IMPORT_WORDS)
    p -= 2.49*(word in SHELL_COMMANDS or word in SQL_STRING_KEYWORDS)
    p -= 0.07*min(5, recent[-40:].count("'")) + 0.09*min(5, syntax)
    p -= 0.19*('_' in recent[-80:])
    p -= 0.35*('{' in recent[-80:] or '}' in recent[-80:])
