        # A comma-separated Rust lifetime parameter, or a trait lifetime bound.
        angle = recent.rfind('<') > recent.rfind('>')
        rust = bool(re.search(r'\b(?:impl|struct|enum|trait|dyn)\b', recent))
        if rust and (angle or recent.rstrip().endswith('+')):
            return 4.4
        p = spaced_quote(previous, recent)
        if right and not right.isspace():
