            return 5.5
        if c == '$':
            return 4.0
        if c and unicodedata.name(c, '').startswith('GREEK '):
            return 3.0
        if '$' in recent[-80:] and re.search(r'\b[A-Za-z]$', recent):
            return 2.6
        if previous.lower() in {'f', 'r', 'b', 'u', 'fr', 'rf', 'br', 'rb'}:
            return -2.6
        if recent.rstrip().endswith(('<', '&')):
            return 3.0
        return -0.15
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent = '', ''
    else:
        _, previous, recent = carry
    token = prefix.token_strings[-1]
    p = value(token, previous, recent)
    if not recent and not any(ch in token for ch in "'‘’′"):
        p = 0.45 if token[:1].isupper() else 0.20
    return (doc, token, (recent + token)[-160:]), AMPLITUDE_SHRINKAGE * float(p)

