"""Single-quote and curly-quote tokens, read by what they are doing.

Rust lifetimes ("<'a>", "&'a") are strongly positive, and so is a quote
after a math symbol ("$b$'s"). A closing quote after . or ) is positive,
and so is a curly left quote ‘. A straight quote with a space before it
(" '") is positive in prose and negative in code: its sign follows how
much code punctuation (= ( ) ; { } / _) is in the tokens just before it.
A quote that opens a string in code is negative: an f-string opener
("f'"), or a quote glued to = ( or to a path or underscore ("('",
" './", " '__"). Contraction endings ("'s", "'t") and quotes inside
words are 0, and so is every token without a quote.
"""

READS = ()
CODE = set("{}();=<>[]_$#/\\")
CODE_START = "_./\\@"
LIFETIME = ("<'", " <'", "&'", " &'")


def code_density(tokens):
    if not tokens:
        return 0.0
    return sum(any(c in t for c in CODE) for t in tokens) / len(tokens)


def step(carry, prefix, upstream):
    ts = prefix.token_strings
    tok = ts[-1]
    prev = ts[-2] if len(ts) > 1 else ""
    if tok in LIFETIME:
        return carry, 5.0
    if tok in (".'", ")'"):
        return carry, 3.0
    if tok == "‘":
        return carry, 2.2
    if tok == "'":
        if prev.strip("( ") == "f":
            return carry, -3.2
        if prev.endswith("$"):
            return carry, 5.0
        return carry, 0.0
    body = tok.lstrip(" ")
    if body[:1] in ("'", "‘"):
        if body[1:2].isalpha():
            return carry, 0.0
        if not tok.startswith(" "):
            return carry, 0.0
        if tok == " ‘":
            return carry, 0.9
        if body[1:2] and body[1:2] in CODE_START:
            return carry, -1.4
        prose = code_density(ts[-41:-1]) < 0.05
        if prose:
            return carry, 1.6 if prev[-1:].isalpha() else 0.1
        return carry, -0.5 if prev[-1:].isalpha() else -1.2
    if body[:1] in ("=", "(", ":", ",") and body[1:2] in ("'", "‘"):
        return carry, -1.2
    return carry, 0.0

