"""A document-onset pulse, scaled by the first token's visible form.

Digits, isolated letters and document-formatting symbols get larger pulses;
ordinary words (especially leading-space words) get smaller ones. Word frequency
helps distinguish complete common words from short fragments. Once the initial
run of identical tokens ends, the prediction is zero.
"""
import math
import regex
from wordfreq import zipf_frequency

READS = ()


def onset(s):
    w = s.strip()
    spaced = s.startswith(' ')
    if s == '<|im_start|>':
        return 2.65
    if s == '<|endoftext|>':
        return 10.9
    if s == '<|im_end|>':
        return 3.0
    if s.startswith('<|'):
        return 0.0
    if not w:
        if '\n' in s:
            if '\r' in s:
                return 10.0 + 2.0 * (s.count('\n') > 1)
            if s.startswith(' '):
                return 6.4
            if '\t' in s:
                return 8.3
            return 3.8 + 1.6 * min(2, s.count('\n') - 1)
        if '\t' in s:
            return 0.0 if ' ' in s else 9.2 if len(s) == 1 else 3.4
        if not s.isascii():
            return 8.2
        return 2.5 if len(s) == 1 else -0.7
    if w.isascii() and w.isdigit():
        return 5.5 + 0.62 * int(w[0]) + (w[0] == '0')

    # Import syntax, question labels, and common subject starters.
    if not spaced and w in {'import', 'from', '#include'}:
        return 8.0
    if not spaced and w in {'Q', 'Question'}:
        return 11.5
    if w.lower() == 'it':
        return 6.2 + 3.8 * (w == 'It' and not spaced)
    if w.lower() == 'there':
        return 3.8
    if w.lower() in {'a', 'the'}:
        return -1.4
    if w.lower() == 'an':
        return 2.4

    if regex.fullmatch(r'\p{Latin}+', w):
        n = len(w)
        f = zipf_frequency(w, 'en')
        return (4.52 - 0.70 * spaced + 1.17 * w[0].isupper()
                + 1.12 * (w.isupper() and n > 1) + 3.24 * (n == 1)
                - 1.47 * math.log1p(n) - 0.35 * f
                - 0.26 * (f >= 6) - 0.97 * (f < 2))

    # Markup headings and comment/docstring openers.
    if set(w) == {'#'}:
        return 15.0 if len(w) <= 2 else 2.0
    if w.startswith('//'):
        return -2.5 if '\n' in s else 6.8
    if w.startswith(('/*', '"""', "'''")):
        return 20.0 if '\n' in s else 7.5
    if w == '<':
        return 3.0 if spaced else 19.5
    if w == r'\t':
        return 15.3
    if w.startswith('\\') and len(w) > 1:
        return 10.5
    if not any(c.isalnum() for c in w):
        if w == '.' and spaced:
            return 14.8
        if w in {'$', '%', '*', '\\'}:
            return 6.3
        if spaced:
            return 4.6 if '\n' in s else 2.3
        if w == ',':
            return 5.9 if '\n' in s else -1.0
        if w in {'(', ')', '}'}:
            return 0.7
        if w == '{':
            return 6.8
        if w in {'[', ']'}:
            return 2.9
        if w == '.':
            return 10.0 if s.count('\n') == 1 else 5.8 if '\n' in s else 4.2
        if all(c in '\'"`' for c in w):
            return 5.5
        return 2.7 + 2.0 * ('\n' in s)
