        return 1.1
    if regex.search(r'\p{Cyrillic}', w):
        return 8.0 if len(w) == 1 and w.isupper() and not spaced else 1.8
    if regex.search(r'\p{Arabic}', w):
        return 4.3
    if regex.search(r'\p{Thai}', w):
        return 6.4
    return 2.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = onset(prefix.token_strings[-1])
        return (doc, token, value, True), float(value)
    doc, first, value, initial_run = carry
    initial_run = initial_run and token == first
    return (doc, first, value, initial_run), float(value if initial_run else 0.0)

"""A document-onset pulse with a readable estimate of its amplitude.

Predict at the first token, preserve that value through an uninterrupted
repetition of that token, then predict zero until a new document starts.
Amplitude uses whitespace, length, case, digits, punctuation and script;
English words also use frequency and broad grammatical/syntactic classes.
These rules omit token-specific quirks and small later-token activations.
"""
import regex
from wordfreq import zipf_frequency
from wordnet import parts_of_speech

READS = ()
DEMONSTRATIVES = {'this', 'that', 'these', 'those'}
THIRD_PERSON = {'he', 'she', 'it', 'they'}
DECLARATIONS = {'def', 'class', 'struct', 'enum', 'function',
                'import', 'package', 'namespace', 'using', 'from'}


def opening_value(s):
    if s == '<|endoftext|>':
        return 16.0
    if s.startswith('<|'):
        return -3.38 if s == '<|im_start|>' else -0.8
    if s.isspace():
        if s == '\t':
            return 11.1
        return 7.0 if '\n' in s else 5.6
    if s in {r'\n', r'\t'}:
        return 12.3
    w = s.strip()
    if not w:
        return 0.0
    spaced = s[0].isspace()
    if w.isdecimal():
        return 6.5 if w == '0' else 4.6
    if w.isascii() and w.isalpha():
        n = min(len(w), 10)
        low = w.lower()
        frequency = zipf_frequency(low, 'en')
        content_word = bool(parts_of_speech(low))
        if spaced:
            value = 0.85 + 0.16*frequency - 0.26*n
            value += 2.0*(n == 1) + 0.6*w.istitle() - 0.5*content_word
        else:
            value = 4.1 + 0.16*frequency - 0.49*n
            value += 1.3*(n == 1) + 0.85*w.istitle() - 0.2*content_word
        value -= 1.1*low.endswith('ing')
        if low in DEMONSTRATIVES:
            value -= 1.6 if spaced else 3.9
        if low in THIRD_PERSON:
            value -= 1.1 if spaced else 3.45
        if low in {'i', 'we'}:
            value += 0.8 if spaced else 1.2
        if w in DECLARATIONS:
            value += -0.5 if spaced else 3.1
        return value
    if '\ufffd' in w:
        return 3.5
    if not any(c.isalnum() for c in w):
        if w.startswith('/*'):
            return 10.0
        if w.startswith('//'):
            return 7.4
        value = 5.4 - 1.1*spaced + 0.7*('\n' in s)
        value -= 1.5*any(c in '.,:;!?' for c in w)
        if len(w) > 1 and len(set(w)) == 1:
            value += 1.5
        value += 0.4*w.count('^')
        return value
    if regex.search(r'\p{Script=Han}', w):
        return 0.55
    if regex.search(r'\p{Script=Cyrillic}', w):
        return 1.0 if spaced else 3.0
    if regex.search(r'\p{Script=Arabic}', w):
        return 2.2 if spaced else 3.0
    return 2.8 - 0.25*min(len(w), 10) - 1.0*spaced


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = opening_value(prefix.token_strings[-1])
    else:
        value = carry[2] if token == carry[1] else 0.0
    return (doc, token, value), float(value)

programs.haiku:
"""Document-start detector for layers.1.mlp.down_proj:3554.

This component is silent inside a document and fires on the FIRST token of each
document (a row start also counts, since the model resets attention there). Its size
depends only on which token starts the document, not on the context, because at
position 0 attention sees nothing but the token itself. The rules below sort those
first tokens into rough kinds:

  * special chat/end markers (<|im_start|> etc.)          -> strongly negative
  * whitespace, newlines, tabs, indentation               -> high
  * punctuation/symbol starts (#, //, /*, triple quotes, braces)  -> high
  * digits                                                -> high
  * programming keywords (def, class, int, #include ...)  -> high
  * one- or two-letter capitalised starts / abbreviations -> high
  * ordinary capitalised or lowercase words                -> moderate
  * space-prefixed words mid-sentence (" one", " seating") -> near zero or negative
  * CJK / other non-ASCII characters                      -> about zero

Predicts 0 at every other position.
"""

READS = ()

PROGRAMMING_WORDS = {
    "def", "class", "int", "import", "from", "return", "public", "private",
    "static", "void", "var", "let", "const", "function", "package", "using",
    "namespace", "struct", "include", "pragma",
}


def start_value(s):
    """Activation for a document whose first token decodes to the string s."""
    if s.startswith("<|"):
        return -3.4
    body = s.strip()
    if not body:
        return 5.5
    if not body.isascii():
        return 1.0
    if not any(c.isalnum() for c in body):
        return 5.0
    if body.isdigit():
        return 5.0
    if body.isalpha():
        if s[:1] == " ":  # a word continuing a sentence
            if len(body) <= 3:
                return 1.3
            if body.endswith("ing"):
                return -2.0
            return -0.6 if len(body) >= 5 else 0.4
        if body in PROGRAMMING_WORDS:
            return 8.0
        if len(body) <= 2:
            return 5.0
        if body[0].isupper():
            return 3.5
        return 2.3 if len(body) <= 5 else 1.5
    return 0.5


def step(carry, prefix, upstream):
    """Predict the component at the newest position of the prefix."""
    if prefix.position > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        return carry, 0.0  # mid-document: the component is silent
    return carry, start_value(prefix.token_strings[-1])

