        return 3.8
    if s in {'边', '邊'} or s.startswith(('旁边', '旁邊', '一边', '一邊',
                                          '海边', '海邊')):
        return 1.6
    if s in {'ド', 'ディング'} and prev.endswith('サイ'):
        return 8.5
    if s == 'ид' and prev.lower().endswith('с'):
        return 1.7
    return -0.22 if start and not s.startswith('<|') else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    tail, prev = ('', '') if start else carry[1:]
    s = prefix.token_strings[-1]
    value = response(s, prev, tail, start)
    return (doc, (tail + s)[-80:], s), value

"""A spelling-sensitive detector for death, dying, and killing.

Recognize English forms and several corresponding Romance, Russian and CJK
roots. Join unfinished words and UTF-8 characters across tokens. Ambiguous
'die' is strong only after English verb-cue function words or negation.
This conservative rule misses some verb uses but avoids many article/noun uses.
There is a one-token echo on 'death of'. Incidental non-death subword
responses are not modeled; other text is zero.
"""
import codecs
import re

READS = ()
ENGLISH = {
    'death': -6.6, 'deaths': -3.7, 'dead': -3.7,
    'died': -3.2, 'dying': -4.3, 'dies': -1.4,
    'kill': -4.4, 'killed': -4.7, 'killing': -2.8, 'kills': -3.2,
    'murder': -0.5, 'mortality': -0.8,
}
TITLED = {
    'death': -9.8, 'deaths': -7.0, 'dead': -5.0,
    'died': -2.4, 'kill': -3.4, 'killed': -2.1, 'killing': -0.8,
}
VERB_CUES = frozenset('''to will would could should may might must can
not and or i who they we you he she it'''.split())
POSSESSIVES = frozenset('my your his her its our their'.split())
LETTERS = re.compile(r'[^\W\d_]+\Z')


def lexical_value(text, word, old_word, previous):
    bare = text.strip(' \t\r\n_')
    direct = bare.lower()
    split = (text.isalpha() and direct != word and bool(old_word)
             and direct not in ENGLISH)
    root = direct if direct in ENGLISH else word
    if root in ENGLISH and (direct in ENGLISH or old_word not in ENGLISH):
        value = ENGLISH[root]
        if bare[:1].isupper():
            value = TITLED.get(root, value)
            if root == 'death' and not text[:1].isspace():
                value = -7.2
        elif root == 'death':
            if previous in POSSESSIVES:
                value = -4.8
            elif previous in ("'s", '’s'):
                value = -3.6
            elif old_word == 'cell':
                value = -8.5
        if direct == 'kill' and not text[:1].isspace():
            value = -1.8
        if split and root in ('kill', 'killed', 'killing', 'died', 'dying'):
            value = -7.8
        if split and root == 'death':
            value = -14.0 if text.isupper() else -8.0
        return value
    if word == 'die' and (old_word in VERB_CUES
                          or previous in ("n't", "'t", '’t')):
        return -7.0
    if split and word in ('kill', 'killed', 'killing', 'kills', 'killer'):
        return -7.8
    if (word.endswith('mort') and not word.startswith('amort')
            and not old_word.endswith('mort')):
        return -3.5 if bare[:1].isupper() else -6.0
    if word in ('morte', 'mortes', 'morts', 'morto', 'morta', 'morti'):
        return -9.0
    if word.startswith('muert') and not old_word.startswith('muert'):
        return -9.5
    if word in ('morir', 'mourir', 'morire', 'muere', 'mueren'):
        return -5.0
    if word == 'смер' and old_word != word:
        return -3.0
    if word in ('смерть', 'смерти') and word != old_word:
        return -6.5
    if direct == 'of' and previous == 'death':
        return -3.0
    if '死亡' in text:
        return -5.4
    if '死' in text:
        return -9.7 if len(bare) == 1 else -4.4
    if '煞' in text:
        return -2.0
    if '杀' in text or '殺' in text:
        return -1.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', b'')
    _, old_word, previous, tail = carry
    data = tail + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(data, 'ignore', False)
    match = LETTERS.search(old_word + text)
    word = match[0].lower() if match else ''
    value = lexical_value(text, word, old_word, previous) if text else 0.0
    return (doc, word[-32:], text.strip().lower(), data[used:]), value

programs.haiku:
"""Death and killing detector.

What it does: the component is a negative "death / killing" feature. It reads the
word being typed (subword pieces are joined back into the word, so "DE"+"ATH" is
"death") and answers with a negative number on death words. The strongest are
死 (Chinese "die") and "death"; then "killed", "dying", "mort(e)", "dead", "kill",
"died", "killing", "deaths". Weaker words (mortal, murder, 杀) get small values.
English "die"/"dies" count only as the verb, i.e. after "to", "will", "or", "not",
etc.; the German article "die" stays 0. "of" right after a death word ("death of")
is also pushed negative. Every other token predicts 0.
"""
READS = ()

# typical activation for each word, from the data
STRENGTH = {
    "death": -6.7, "deaths": -3.6, "dead": -4.2, "dying": -4.4, "died": -3.2,
    "kill": -4.0, "killed": -4.6, "killing": -3.0, "kills": -3.9,
    "mort": -4.8, "morte": -6.0, "mortal": -1.0, "mortality": -0.7, "murder": -0.4,
    "死": -8.3, "死亡": -5.7, "杀": -1.7, "煞": -2.1,
}
# the English verb "to die", after a word that opens a verb phrase
DIE_VERBS = {"die": -4.0, "dies": -3.0}
ENGLISH_BEFORE = {"to", "will", "would", "may", "might", "can", "could", "must",
                  "shall", "should", "or", "not", "they", "we", "i", "you", "he", "she",
                  "who", "and", "a", "the", "it", "let"}
DEATH_BEFORE_OF = {"death", "deaths", "died", "dead", "killed", "dying"}


def step(carry, prefix, upstream):
    piece = prefix.token_strings[-1]
    before = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    word = piece.strip().lower()
    # rebuild the current word: a piece with no leading space continues the letters before it
    if piece[:1] == " ":
        whole = word
    elif piece[:1].isalpha():
        whole = (carry or "") + word
    else:
        whole = ""
    if word in STRENGTH:
        value = STRENGTH[word]
    elif whole in STRENGTH:
        value = STRENGTH[whole]
    elif word in DIE_VERBS and before in ENGLISH_BEFORE:
        value = DIE_VERBS[word]
    elif word == "of" and before in DEATH_BEFORE_OF:
        value = -2.2
    else:
        value = 0.0
    return whole, float(value)

programs.sol:
"""Detect ton-like spelling fragments, especially split across tokens.

A t-final fragment followed by an on-fragment gives the largest response.
Short ton suffixes also respond without that context; common, long words
containing the same letters respond less. Transliteration extends the same
rule to several other scripts. A two-token tail catches t + o + n spellings.
The contrasting t + um and atum endings are mildly negative. These rules
approximate spelling sensitivity, not shared meanings or exact token scores.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency
import regex

READS = ()

# Syllabic scripts are not treated as if their romanization were Latin text.
SYLLABIC = (
    r'[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}'
    r'\p{Script=Hangul}\p{Script=Thai}]'
)
EAST_ASIAN = (
    r'[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}]'
)
ON_ENDING = r'on(e[s]?|s|ic[s]?|er[s]?|ian[s]?|ation|i|ia|a|g|t)?'
DERIVATIONAL_ENDINGS = {
    's', 'e', 'ed', 'er', 'ers', 'i', 'a', 'ic', 'ics',
    'ical', 'ically', 'ica', 'ique', 'ation', 'ality', 'ing', 'ung',
}


@lru_cache(maxsize=32768)
def spelling(token):
    return anyascii(token).lower()


@lru_cache(maxsize=32768)
def intrinsic(token):
    """Short suffix fragments are stronger than lexicalized whole words."""
    word = spelling(token).strip()
    if regex.search(SYLLABIC, token):
        return 0.0
    m = re.fullmatch(r'(.*)ton(e[ds]?|s|ne[s]?|ic[s]?|i)?', word)
    if m:
        stem = m[1]
        if stem.endswith('ing') or word.endswith(('stone', 'stones')):
            return 0.0
        if not stem or stem == '-':
            return 3.9
        if stem in {'o', 'e', 'i'} and not token.startswith(' '):
            return 3.2 if word.endswith('e') else 5.6
        if stem.endswith('er') and len(stem) <= 3:
            return 4.8
        if (len(stem) <= 2 and not stem.endswith('s')
                and not token.startswith(' ')):
            return 3.3
        value = 3.0
        if stem.endswith(('l', 'r', 'n', 's')):
            value = 1.8
        if len(word) > 7:
            value *= 0.1
        frequency = zipf_frequency(word, 'en')
        if word.endswith('s'):
            frequency = max(frequency, zipf_frequency(word[:-1], 'en'))
        if frequency > 4.0:
            value *= max(0.05, 1 - 1.6 * (frequency - 4.0))
        return value
    if re.fullmatch(r'tun(a|e|ed|ing)?', word):
        return 1.0
    if word == 'tn':
        return 0.6
    if word == 'atum':
        return -1.0
    if token == ' one':
        return -0.15
    return 0.0


def predict(token, previous, before_previous):
    x = spelling(token)
    p = spelling(previous)
    q = spelling(before_previous)
    value = intrinsic(token)
    if not x or x != x.strip() or not x.isalpha():
        return value
    # Title case starts a new name more often than it continues a word.
    if token[0].isupper() and not token.isupper():
        return value
    follows_t = p.endswith('t')
    follows_tr = (p.endswith('tr') and previous.isascii()
                  and x in {'one', 'ones'})
    if follows_t or follows_tr or p.endswith('th'):
        if (re.fullmatch(ON_ENDING, x)
                and not regex.search(r'\p{Script=Thai}', token)):
            value = 7.0 if follows_t else 3.5
            if x in {'oni', 'onia', 'ong'}:
                value *= 0.65
            if p.endswith('st'):
                value *= 0.55
            if regex.search(r'\p{Script=Cyrillic}', token):
                value = 9.0
        elif token in {'ão', 'ون'}:
            value = 5.0
        elif re.fullmatch(r'un(a|e|es|ed|ing|i)?', x):
            value = 3.2
        elif x in {'own', 'rons'}:
            value = 2.4
        elif x in {'en', 'ens'}:
            value = 0.2
        elif x in {'ung', 'ungs'}:
            value = 0.8
        elif token == 'ö':
            value = 2.1
        elif token == 'um':
            value = -2.0
        if 'ton' in x and not x.startswith('ton'):
            value += 2.5
    if x in {'ton', 'tons', 'tone', 'tones'}:
        if p.endswith('ing'):
            value = 1.2
        elif p.endswith('n') or (len(p.strip()) <= 3 and p.endswith('nk')):
            value = 2.4
        elif p.endswith(('e', 'o')):
            value += 1.3
    if follows_t and x in {'onym', 'onyms', 'ony', 'onomic'}:
        value = 1.5
    # The Romance name ending -onio is weaker than bare -on/-one.
    if token == 'onio':
        value = 1.4
    if x == 'on' and p.endswith('to'):
        value = 4.8
    elif x == 'on' and p.endswith('on'):
        value = 1.8
    if p.endswith('th'):
        if x in {'a', 'an'}:
            value = 2.0
        elif x == 'un':
            value = 1.8
    # A final n may arrive one token after the vowel, or in another script.
    if ((q + p).endswith('to') and x.startswith('n') and len(x) <= 3
            and not regex.search(EAST_ASIAN, token)):
        value = 5.5
        if previous == 'ω':
            value = 2.0
    if token in {'ニ', 'ン', 'ナ', 'ネ'} and previous.endswith('ト'):
        value = 5.0
    # Inflection or derivation of a just-completed ton fragment.
    if re.search(r'ton$', q + p) and x in DERIVATIONAL_ENDINGS:
        value = 5.5 if x == 'ed' else 4.2
        if zipf_frequency(p.strip().rstrip('s'), 'en') > 4.0:
            value *= min(1.0, intrinsic(previous) / 3.9)
        if not p or not p[-1].isalpha():
            value = 0.0
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = before_previous = ''
    else:
        _, previous, before_previous = carry
    token = prefix.token_strings[-1]
    value = predict(token, previous, before_previous)
    return (doc, token, previous), float(value)

"""Recognize the leading part of decimal fractions beginning with zero.

Positive responses mark the dot in 0.x, its first digit, and the next digit
when the fraction starts with zero. Longer integers and version strings are
weaker; commas get weak positive responses. Quotes and nearby punctuation
adjust the response. Repeated decimal
forms strengthen the dot response, while later document positions weaken it.

A separate, smaller negative rule recognizes short Latin-letter fragments
that continue an O vowel with U across a small consonant gap. Everything
else is predicted near zero. These spelling rules are only an approximation;
they do not capture all of the component's rare nonnumeric responses.
"""
from functools import lru_cache
from math import log1p

import regex
from anyascii import anyascii

READS = ()
DIGITS = frozenset('0123456789')


@lru_cache(maxsize=8192)
def vowel_fragment(text):
    """A short alphabetic fragment, transliterated to compare vowel shapes."""
    if not regex.fullmatch(r'\p{Latin}+', text):
        return ''
    return anyascii(text).lower()


def rounded_vowel_response(previous, current):
    """A smaller negative response when a fragment continues O with U."""
    p = vowel_fragment(previous.strip())
    s = vowel_fragment(current)
    if not p or not s or len(s) > 4:
        return 0.0
    _, found_o, tail = p.rpartition('o')
    head, found_u, _ = s.partition('u')
    vowels = 'aeiou'
    if not found_o or not found_u:
        return 0.0
    if any(c in vowels for c in tail + head):
        return 0.0
    gap = len(tail) + len(head)
    if sum(c in vowels for c in s) != 1:
        return 0.0
    if gap == 1:
        return -3.3 if len(p) <= 2 else -1.8
    return -0.45 if gap == 2 else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, history, position, fractions = carry if carry else (None, (), -1, 0)
    if doc != old_doc:
        history, position, fractions = (), -1, 0
    position += 1
    s = prefix.token_strings[-1]
    # Four preceding token strings, oldest to newest.
    a, b, c, d = (('',) * 4 + history)[-4:]
    value = rounded_vowel_response(d, s)
    stage, context = 0, ''
    if s == '.' and d == '0':
        fractions += 1
        value = 3.6 + 0.6 * log1p(fractions) - 0.26 * log1p(position)
        context = c
        stage = 1
        if c in DIGITS:
            value = 0.1
        elif c == '.':
            value = 0.8
    elif s in DIGITS:
        if d == '.' and c == '0':
            value = 4.7 + (1.0 if s in ('0', '1') else 0.0)
            value += 0.17 * log1p(fractions) - 0.23 * log1p(position)
            stage, context = 2, b
            if b in DIGITS:
                value = 0.8
            elif b == '.':
                value = 1.4
        elif d == '0' and c == '.' and b == '0':
            value = 3.5 if s in ('0', '1') else 3.1
            stage, context = 3, a
            if a in DIGITS:
                value = 0.3
        elif d == ',' and c == '0' and b not in DIGITS:
            value = 0.5
    elif s == ',' and d == '0' and c not in DIGITS:
        value = 0.25
    if stage and context not in DIGITS and context != '.':
        ending = context.rstrip().lower()
        if ending.endswith('v'):
            value -= (1.3, 1.1, 0.6)[stage - 1]
        elif any(c in context for c in "'\""):
            value -= (1.0, 0.7, 0.5)[stage - 1]
        elif ending.endswith('='):
            value -= (0.7, 0.3, 0.0)[stage - 1]
        elif ending.endswith('-'):
            value += (0.3, -0.7, -0.3)[stage - 1]
        elif ending.endswith('('):
            value += (0.5, 0.0, -0.6)[stage - 1]
    if stage:
        value = max(0.0, value)
    return (doc, (history + (s,))[-4:], position, fractions), value

"""A sparse boundary signal: non-English 'and', inline comments and stops.

A short recent text buffer disambiguates conjunctions from English fragments
and algebraic letters. Language evidence comes from dictionary word frequencies.
Other rules cover numbered versus prose stops, XML summary tags, repeated
middle dots, and a negative prior at document beginnings.
Unmatched positions return zero; the context buffer resets for each document.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

# Coordinating conjunctions, their languages and their typical response sizes.
CONJUNCTIONS = {
    'et': (('fr', 'it'), 0.72),
    'e': (('pt', 'it'), 0.85),
    'ed': (('it',), 0.85),
    'y': (('es',), 0.74),
    'dan': (('id',), 0.63),
    'ja': (('fi',), 0.85),
    've': (('tr',), 0.54),
    'en': (('nl',), 0.75),
    'si': (('ro',), 0.80),
}
OTHER_AND = {
    'und': 0.34, 'og': 0.78, 'och': 0.69,
    'și': 0.53, 'şi': 0.71, 'és': 0.34, 'і': 0.37, 'و': 0.33,
}

@lru_cache(maxsize=50000)
def frequency(word, language):
    return zipf_frequency(word, language)


def language_evidence(text, languages):
    words = re.findall(r'[^\W\d_]{2,}', text.lower())[-20:]
    if not words:
        return 0.0
    return max(sum(max(-3, min(3, frequency(w, lang) -
                              frequency(w, 'en'))) for w in words) / len(words)
               for lang in languages)


def response(token, previous, text, initial):
    bare = token.strip()
    word_start = token.startswith(' ') or not text or not text[-1:].isalpha()
    if word_start and bare.lower() in CONJUNCTIONS:
        langs, amplitude = CONJUNCTIONS[bare.lower()]
        evidence = language_evidence(text[-180:], langs)
        gate = max(0.0, min(1.0, (evidence - 0.15) / 1.3))
        if previous.rstrip().endswith(','):
            amplitude += 0.17
        return 0.02 + (amplitude - 0.02) * gate
    if (word_start and bare.lower() in OTHER_AND
            and (bare == bare.lower() or bare == 'Und')):
        value = OTHER_AND[bare.lower()]
        if bare == 'Und':
            value = 0.56
        return value + (0.17 if previous.endswith(',') else 0.0)
    # Greek 'and', including its older spelling, may cross token boundaries.
    greek = re.search(r'(?:^|\s)(και|καὶ)$', (text + token)[-8:])
    if greek:
        return 1.31 if greek[1] == 'και' else 0.86
    if initial:
        return -0.26
    if bare and set(bare) == {'·'} and len(bare) > 1:
        return -1.58 if text.endswith('··') else 0.0
    line = text.rsplit('\n', 1)[-1]
    if bare == 'summary' and text.rstrip().endswith(('<', '</')):
        return 0.85
    if re.fullmatch(r'[();{}\[\]]+//', bare):
        return 0.82
    if bare in {'//', '//#', '/*'} and '\n' not in token:
        if not line.strip():
            return -0.03
        if previous.isspace():
            return 0.20 if line.strip().isdigit() else 0.35
        if previous.rstrip().endswith((';', ')', '}', ':')):
            return 0.85
        return 0.16
    if token == ' #':
        if previous.rstrip().endswith((';', ')', ']', ':')):
            return 0.70
        if previous.isspace() and line.strip():
            return 0.29 if line.strip().isdigit() else 0.50
        return -0.04
    # Full stops after numbers/parentheses are stronger than after prose words.
    if bare in {'.', ').'}:
        digit = previous.rstrip()[-1:].isdigit()
        if token.startswith(' '):
            if previous.isspace():
                return 0.0
            if not any(c.isalnum() for c in previous):
                return -0.04 if previous.startswith(' ') else 0.11
            return 0.32 if digit else 0.21
        if token.count('\n') >= 2:
            return 0.05 if digit else -0.01
        if '\n' in token:
            return 0.13 if digit else 0.04
        if bare == ').':
            return 0.13 if digit else 0.05
        if digit:
            if line.strip().isdigit():
                return -0.05  # a numbered list marker, not a prose stop
            number = re.search(r'\d+$', text)
            length = len(number[0]) if number else 1
            return min(0.28, 0.06 + 0.11 * (length - 1))
        return 0.05 if not previous.startswith(' ') else 0.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    _, text, previous = (doc, '', '') if initial else carry
    token = prefix.token_strings[-1]
    value = response(token, previous, text, initial)
    return (doc, (text + token)[-240:], token), float(value)

"""Formatting-boundary pulses, with document-start baselines.

Negative pulses mark split TeX commands, numbered headings and code fences
following a blank line. A hash used as heading content gives a positive pulse.
At document starts, punctuation and a few grammatical classes have separate
baselines. Pulse sizes emphasize the training positions with high causal
importance; this is an approximation, not a parser of the surrounding topic.
"""
import re

READS = ()
WEEKDAYS = set('Monday Tuesday Wednesday Thursday Friday Saturday Sunday'.split())
PRONOUNS = set(
    'i we you he she it they me us him her them this that these those there'.split()
)
PREPOSITIONS = set(
    'in on at to from with by for of as into over under through about'.split()
)
AUXILIARIES = set('am is are was were be been being have has had having'.split())
# Punctuation tokens at the start of an otherwise unseen document.
INITIAL = {
    ' ': -0.22, '\t': -0.44, '\n': 0.10, '\n\n': 0.13,
    '\\t': -2.36, '\\n': -0.88, '\\"': 1.45,
    '.': -0.18, ',': -0.02, ':': -0.19,
    '.\n': 0.77, '.\n\n': 0.09,
    '(': 0.27, ' (': 0.46, ')': -0.59,
    '-': -0.41, ' -': 0.18, ' +': 0.49,
    '"': 0.20, ' "': -0.26, '/': -0.33,
}
DIGITS = (-0.33, 0.08, -0.37, -0.47, -0.05,
          -0.07, -0.08, -0.15, -0.04, 0.19)


def predict(s, previous, before_previous, line, initial):
    t = s.strip()
    if t and set(t) == {'⎯'}:
        return 1.16
    if len(t) > 1 and set(t) == {'·'}:
        return -0.33
    if previous.endswith('$'):
        if t.startswith(('\\', '{\\')):
            if previous.endswith(('($', '"$')):
                return -2.5
            if previous.strip() == '$$':
                return -0.9
            return -1.1
        if t.startswith('^'):
            return -1.1
    if previous == '``' and s == '`\n':
