from functools import lru_cache
import regex
import cedict

READS = ()

VALUES = {
    'other': 0.0015,
    'title_colon': 3.22,
    'middle_dots': 1.13,
    'import_first': -1.37,
    'import': -0.83,
    'destructure': -0.35,
    's_word_beginning': 0.7,
    'control': -0.8,
    'hold': -0.1,
    'support': -0.5,
    'control_character': -0.07,
    'hold_character': -0.45,
    'collective': -0.9,
    'design': -0.35,
    'definition': -0.2,
    'concession': -0.56,
    'hope': -0.26,
}


@lru_cache(maxsize=16384)
def chinese_cue(text):
    if not regex.fullmatch(r'\p{Script=Han}+', text):
        return 'other'
    # Possessive 的 sometimes shares a token with a whole word.
    word = text[1:] if len(text) > 2 and text.startswith('的') else text
    # 持 means hold/sustain; 控 means control.
    if len(word) == 1:
        if word == '持':
            return 'hold_character'
        if word == '控':
            return 'control_character'
        return 'other'
    senses = cedict.glosses(word)
    primary = senses[0].lower() if senses else ''
    if '控' in word:
        if primary == 'to control' or 'controlling number' in primary:
            return 'control'
    if '持' in word:
        if any(g in senses for g in ('to support', 'to help', 'to assist')):
            return 'support'
        return 'hold'
    if (primary.startswith('collective')
            or (primary == 'group' and 'bloc' in senses)):
        return 'collective'
    if primary.startswith('to design'):
        return 'design'
    if primary.startswith('definition'):
        return 'definition'
    if primary.startswith('although'):
        return 'concession'
    if primary.startswith('to hope'):
        return 'hope'
    return 'other'


def cue(text, previous, position):
    if text == ':' and previous == 'Title' and position == 1:
        return 'title_colon'
    if text and set(text) == {'·'} and len(text) >= 2:
        return 'middle_dots'
    if text == ' {':
        keyword = previous.strip().lstrip('+-')
        if keyword == 'import':
            return 'import_first' if position == 1 else 'import'
        if keyword in ('export', 'const', 'let', 'var'):
            return 'destructure'
