    if previous.lower().endswith('s'):
        beginning = 's' + text.lower()
        if beginning in ('syn', 'schem', 'scho', 'sno', 'sorg'):
            return 's_word_beginning'
    if previous.endswith(('с', 'С')) and text == 'ю':
        return 's_word_beginning'
