import re
from functools import lru_cache
import wordnet

READS = ()
VERBS = {
    'visual': {'see', 'observe'},
    'evidence': {'show', 'suggest', 'indicate', 'demonstrate',
                 'reveal', 'prove', 'imply'},
    'thought': {'know', 'think', 'believe', 'assume', 'understand', 'realize',
                'appreciate', 'find', 'notice', 'note'},
    'speech': {'say', 'tell', 'state', 'argue', 'conclude', 'mean'},
    'appearance': {'seem', 'appear'},
}
HEADINGS = {'explanation', 'solution', 'answer', 'step', 'example', 'result',
            'summary', 'conclusion', 'discussion', 'analysis', 'approach',
            'method', 'procedure', 'detail', 'instruction', 'output', 'input',
            'description', 'definition', 'proof', 'reason', 'feature', 'goal',
            'objective', 'rule', 'proposition', 'lemma', 'theorem', 'equation',
            'observation', 'test', 'question'}
