                     r'equations?|formula|figure|fig|eq|graph|above|understanding|'
                     r'perspective|view|definition|problem|statement)\b', re.I)

@lru_cache(maxsize=32768)
def bases(s):
    w = s.strip().lower()
    return frozenset(wordnet.base_forms(w)) | {w}

@lru_cache(maxsize=32768)
def verb(s):
    w = s.strip().lower()
    if w.isascii() and w.isalpha() and len(w) >= 3:
