    if p in {'be','been','have','has','had'}:
        return {'visual': 0.21, 'evidence': 0.36}.get(group, 0.14)
    if p in {'can','could'}:
        return 0.34
    if p in {'it','this'}:
        return 0.10
    if p == 'i' and group == 'thought':
        return 0.16
    if p == 'to':
