        return None, 0.1 if prev in NOT_INTRO_NEWLINE else 0.65
    if tok in COLONS:
        return None, 0.65 if (prev in INTRO or prev in HEADINGS) else 0.13
    if tok in NEWLINES:
        return None, 0.6 if prev in HEADINGS else 0.0
    if tok == ",":
        if prev in SUMMARY_WORDS or sentence_start_word(prefix) in SOURCE_OPENERS:
            return None, 0.45
        return None, 0.0
    if word in SEE_VERBS and prev in SEE_CONTEXT:
        return None, 0.6
    if word in REPORT_VERBS:
        return None, 0.25
    if tok in CHINESE_LOOK:
        return None, 0.4
    return None, 0.0

programs.sol:
"""A sparse spelling and time-phase predictor.

Unfinished mid-/mi- spellings are negative; aid-/eid-like spellings are
positive, including a few cross-script equivalents. Early, late, and the
space introducing a date have negative responses too. Completed words,
identifier suffixes, and LaTeX's \\mid are treated differently from word
pieces. These rules approximate the large responses, not the small noisy
activation on ordinary text.
"""
import re
from anyascii import anyascii

READS = ()
ID_ENDINGS = {'id', 'ide', 'ids', 'idd', 'iden', 'ider', 'ida',
              'idi', 'ido', 'ides', 'idos', 'idis', 'idel', 'idl'}
D_ENDINGS = {'d', 'de', 'da', 'dee', 'δ', 'д', 'د', '드', 'ド', '든', 'τ'}
MONTHS = {'january', 'february', 'march', 'april', 'may', 'june',
          'july', 'august', 'september', 'october', 'november', 'december'}
TEMPORAL_PREPOSITIONS = {'in', 'by', 'from', 'until', 'since', 'before', 'after'}
CODE = re.compile(r'[={}\\]|\w+\([^)]*$|;[^.]*$')


def predict(history, token):
    s = token.strip()
    low = s.lower()
    match = re.search(r'([^\W\d_]+)$', history)
    raw_word = match[0] if match else ''
    word = raw_word.lower()
    joined = bool(word) and token == token.lstrip() and not token.startswith('_')
    code = bool(CODE.search(history[-70:]))

    # Persian mi is a verb prefix; inside a word m+i is much weaker.
    if token in {'ی', 'ى', 'ي', 'ید'} and history.endswith('م'):
        if token == 'ی':
            return -16.2 if word == 'م' else -4.0
        if token == 'ى':
            return -13.0 if word == 'م' else -1.0
        if token == 'ید':
            return -6.0
        return -4.0 if word == 'م' else 0.0

    if low.lstrip('_(') == 'mid':
        if history.endswith('\\'):
            return 0.0
        if code or token.startswith('_'):
            return -3.6
        return -7.5 if s.islower() and token.startswith(' ') else -6.0
    if low in {'midi', 'midst', 'amid', 'humid'}:
        return -4.1 if low == 'midi' else -1.35
    if low in {'early', 'late'} and not joined:
        if word == 'too':
            return -0.1
        date = word in {'in', 'by', 'from', 'until', 'since', 'during', 'the'}
        if low == 'late':
            return -4.5 if date else -2.6
        return -2.7 if date else -1.35

    if low in {'aid', 'aide', 'aides', 'aids'}:
        if low != 'aid':
            return 1.2 if low == 'aids' else 5.4
        if word.endswith('afores'):
            return 0.0
        if word == 'first':
            return 13.5
        if word == 'state':
            return 6.8
        if s[0].isupper() or word == 'kitchen':
            return 7.8
        if word in {'to', 'can', 'could', 'will', 'would'}:
            return 1.3
        return 3.75
    if low == 'raid':
        return 0.0 if word.endswith('af') else 3.2
    if s == 'Eid':
        return 6.0
    if s == 'Reid':
        return 1.85

    if joined and (low in ID_ENDINGS or s == 'ид'):
        # Camel-case Id and word+ID are ordinarily programming identifiers.
        if s == 'Id' or (s == 'ID' and not raw_word.isupper()):
            return 0.0
        ending = 'id' if s == 'ид' else low
        previous = anyascii(word).lower()
        if previous.endswith('m'):
            if ending in {'id', 'ids'}:
                if len(previous) == 1:
                    return -6.8 if s == 'ид' else -10.6
                if len(previous) == 2 and previous[0] not in 'aeiou':
                    return -12.0
                return -4.3
            return -3.0
        if previous.endswith(('a', 'e')):
            return 5.5 if ending in {'id', 'ide', 'iden', 'idel'} else 2.8

    if s in D_ENDINGS and joined:
        previous = anyascii(word).lower()
        if s == 'د' and word.endswith(('ای', 'اي')):
            return 6.0
        if s in {'드', '든'}:
            if word.endswith('미'):
                return -7.8
            if word.endswith('이'):
                return 2.0 if s == '드' else 0.8
        if s == 'д' and word.endswith('й'):
            return 4.5
        if s in {'δ', 'τ'} and previous.endswith(('ai', 'ei')):
            return 7.9 if s == 'δ' else 2.1
        if s == 'δ' and previous.endswith('i'):
            return 1.7
        if s in {'d', 'de', 'da', 'dee'}:
            if previous.endswith(('ay', 'ey', 'ai', 'ei')):
                return 3.5
            if previous.endswith(('mi', 'my')):
                return -4.0
    if low in {'itt', 'itten', 'iddle', 'iddles'} and joined and word == 'm':
        return -2.5
    if low == 'te' and joined and word == 'mit':
        return -5.3

    if token in {' ', '-'}:
        if word in {'mid', 'late', 'early'}:
            if token == '-':
                return -7.0 if word == 'mid' else -1.7
            if word == 'mid':
                return -1.0 if code else -7.0
            return -6.0 if word == 'late' else -5.3
        if token == ' ':
            if re.search(r'\b(in|during|since|until|of|at) the$', history, re.I):
                return -1.47
            if word == 'the':
                return -0.89
            if word in MONTHS or word in TEMPORAL_PREPOSITIONS:
                return -0.25
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else b''
    raw = prefix.token_bytes[-1]
    history = previous.decode('utf-8', errors='ignore')
    token = prefix.token_strings[-1]
    if '\ufffd' in token:
        token = (previous + raw).decode('utf-8', errors='ignore')[len(history):]
    value = predict(history, token)
    return (doc, (previous + raw)[-240:]), value

programs.haiku:
"""Activation of layers.1.mlp.down_proj:3567, written as a short lexicon of time-period words.

What it does
- Negative on the words 'mid', 'late' and 'early' (as in "in the mid-1990s", "late 1914").
  The effect is strongest on 'mid'.
- Negative on the space token that comes right after 'mid', 'late' or 'early', and more weakly
  on the space after 'the' when 'the' follows 'in', 'during', 'by', 'of' etc. In both cases the
  next token is about to be a decade or century number ("late 1914", "in the 1990s").
- Positive on the 'aid' family ('Aid', 'aid', 'aide', 'raid'), e.g. "Kitchen Aid", "Job Aid".
- Strongly negative on the Persian present-tense prefix: the 'ی' that follows the 'م' prefix
  (می + verb).
Everything else predicts 0.
"""

READS = ()

PERIOD_WORD = {"mid": -7.0, "midst": -2.0, "late": -3.3, "early": -1.8, "amid": -1.0}
AID_WORD = {"aid": 5.0, "aide": 5.0, "raid": 3.0, "raids": 1.5, "aids": 2.0}
THE_AFTER = {"in", "during", "at", "by", "since", "until", "from", "of", "on", "for", "within"}


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    word = tokens[-1].strip().lower()
    prev = tokens[-2].strip().lower() if len(tokens) > 1 else ""
    before = tokens[-3].strip().lower() if len(tokens) > 2 else ""
    value = 0.0
    if word in PERIOD_WORD:
        value = PERIOD_WORD[word]
    elif word in AID_WORD:
        value = AID_WORD[word]
    elif tokens[-1] == "ی" and prev == "م":
        value = -16.0
    elif set(tokens[-1]) == {" "}:
        if prev in PERIOD_WORD:
            value = -6.0
        elif prev == "the" and before in THE_AFTER:
            value = -1.2
    return carry, float(value)

programs.sol:
"""Short spelling fragments get negative pulses; ordinary tokens stay near zero.

Consonant-only continuations and short hyphenated fragments get the largest
pulses. An unfamiliar running word-prefix following a familiar prefix makes
an internal consonant fragment stronger. Capital initials are a weaker case.
Spelling is also checked after dictionary transliteration. Frequencies are
fixed corpus counts in English, German, French, and Russian; they are not
token identities. The small running alphabetic prefix resets at boundaries.
"""
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
VOWELS = frozenset('aeiouy')


@lru_cache(maxsize=65536)
def frequency(word):
    if not word:
        return 0.0
    languages = ('en', 'de', 'fr', 'ru')
    return max(zipf_frequency(word, lang) for lang in languages)


def pulse(token, previous, before, after):
    text = token.strip()
    letters = text.lstrip('-_')
    lower = letters.lower()
    latin = bool(lower) and all('a' <= c <= 'z' for c in lower)
    roman = anyascii(letters).lower()
    hyphen = text.startswith('-')
    if len(text) > 4 or (not hyphen and len(roman) > 2):
        return 0.005
    old_f, new_f = frequency(before), frequency(after)
    letter_f = zipf_frequency(lower, 'en') if latin else 0.0
    capital = letters[:1].isupper()

    if hyphen:
        if new_f > 4.875:
            if not (latin and any(c in VOWELS for c in lower)):
                if previous[:1].isspace():
                    return -1.76 if capital else -3.03
                return -1.37 if len(before) > 1 else -0.26
            return -0.32
        if len(before) > 1:
            if not letters and not token[:1].isspace():
                return -1.35 if old_f > 4.375 else -0.58
            if letters and new_f > 3.625:
                return -0.44
        return 0.005

    if len(after) <= 3:
        initial = latin and len(letters) == 1 and lower not in VOWELS
        if initial and len(before) > 2:
            return -0.45 if capital and old_f <= 5.625 else -0.09
        return 0.005
    if not any(c in VOWELS for c in roman):
        if letter_f > 4.875 and old_f > 4.125 and new_f <= 1.125:
            return -1.46
        return -0.35 if len(previous.strip()) > 2 else -0.15
    if roman and roman[-1].isalpha() and roman[-1] not in VOWELS:
        if new_f <= 1.125 and old_f > 1.875 and len(before) > 2:
            return -0.38
    return -0.03


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, before = '', ''
    else:
        previous, before = carry[1:]
    after = before
    for character in token:
        after = (after + character)[-40:] if character.isalpha() else ''
    return (doc, token, after), pulse(token, previous, before, after)

"""A sparse detector for contact templates and orthographic fragments.

Example-domain emails and bracketed privacy placeholders receive large
positive values; ordinary email domains receive smaller ones. Additional
rules recognize repeated code fences, two initial Python keywords, initial
tabs/nonbreaking spaces, an isolated Latin-1 UTF-8 lead byte, Thai vowel/tone
clusters, Tamil stop/nasal pulli, and Japanese verb/kana fragments.
The signs and sizes are empirical approximations, not linguistic meanings.
All unrecognized contexts return zero; document boundaries clear the tail.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = b''
    else:
        tail = carry[1]
    previous = tail.decode('utf-8', 'replace')
    token = prefix.token_strings[-1]
    value = 0.0
    if token == '@example':
        value = 8.7 if previous.endswith('email') else 4.1
    elif token in ('.org', '.com', '.net'):
        if previous.endswith('@example'):
            if previous.endswith('firstname.lastname@example'):
                value = 11.3
            elif previous.endswith('email@example'):
                value = 8.7
            else:
                value = 4.0
        elif re.search(r'@[A-Za-z0-9-]+$', previous):
            value = 1.35
    elif token.lower() == ' protected':
        if re.search(r'\[email$', previous, re.I):
            value = 10.5
        elif previous.endswith('Password'):
            value = 3.8
    elif token == '.lastname' and previous.endswith('firstname'):
        value = 1.7
    elif token == 'EMAIL':
        if previous.endswith('<'):
            value = 16.0
        elif previous.endswith('|||'):
            value = 10.0
    elif token == 'NAME' and previous.endswith('<'):
        value = 19.0
    elif token == 'filename' and previous.endswith('<'):
        value = 5.5
    elif token.strip('|') == '' and token:
        if previous.endswith('EMAIL_ADDRESS'):
            value = 8.0
        elif previous.endswith('EMAIL_ADDRESS||'):
            value = 6.5
        elif (previous + token).endswith('|||') and re.search(
            r'(?:email|address)\s+\|*$', previous, re.I
        ):
            value = 8.0
    elif token == '```' and previous.endswith('``'):
        value = 4.6
    elif not previous and token in ('def', 'import'):
        # Python declarations at the start of a packed document.
        value = -3.4 if token == 'def' else -1.15
    elif not previous and token in ('\t', '\xa0'):
        value = 2.1
    elif prefix.token_bytes[-1] == b'\xc2':
        # An isolated UTF-8 lead byte for the Latin-1 supplement.
        value = 1.9
    elif token.startswith('\x80') and previous.endswith('â'):
        # Latin-1 mojibake of UTF-8 punctuation.
        value = 3.5
    elif token.startswith('்'):
        # Tamil pulli: hard consonants, then velar/palatal/dental nasals.
        if previous[-1:] in set('கசடதபற'):
            value = -7.0
        elif previous[-1:] in set('ஙஞந'):
            value = -5.2
    elif token == 'ว':
        # Thai wo waen following a written vowel, especially vowel+tone.
        if previous.endswith('ั่'):
            value = 9.5
        elif previous.endswith('้า'):
            value = 5.0
        elif previous[-1:] in set('ะีุ'):
            value = 2.0
    elif token == '่':
        # Mai ek following a short above/below vowel sign.
        value = {'ั': 5.8, 'ิ': 1.1, 'ุ': 2.6}.get(previous[-1:], 0.0)
    elif token == 'しま':
        # The Japanese shima- verb/auxiliary fragment.
        value = -1.6
    elif token in 'えけげせべぺめれ' and len(token) == 1:
        # E-vowel kana, excluding the common grammatical particles.
        value = -0.7
    return (doc, (tail + prefix.token_bytes[-1])[-300:]), value

programs.haiku:
"""Email-address and personal-data placeholders (layers.1.mlp.down_proj:3570).

The component is near zero on almost every token. Its large values come from one situation:
the text is writing an email address that is a made-up or redacted placeholder, and it fires
on the token that completes that placeholder:
  * ".org" of "firstname.lastname@example.org" (very strong), or ".com" of "email@example.com"
    written in prose (strong; in code like "test@example.com" it stays weak);
  * "@example" in "email@example.com" when "mail" appears within the last few tokens
    (strong), or after a "firstname.lastname" style name (moderate);
  * " protected" in the obfuscated "[email protected]" shown on some web pages;
  * "NAME" and "EMAIL" written as "<NAME>" or "<EMAIL>" placeholders;
  * the bars after "EMAIL_ADDRESS" in redaction-style text;
  * "_NUMBER" after "PHONE" in a template or variable name.
Everything else is predicted as 0. Real addresses such as "@gmail.com" do not fire.
"""
READS = ()


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    t = len(toks) - 1
    s = toks[t]
    prev = toks[t - 1] if t > 0 else ""
    near = "".join(toks[max(0, t - 3):t])
    wide = "".join(toks[max(0, t - 6):t]).lower()
    v = 0.0
    if s in (".org", ".com") and "@" in near and "example" in near:
        v = 11.0 if s == ".org" else (8.0 if "mail" in wide else 2.0)
    elif s in ("@example", "example") and "mail" in wide:
        v = 8.0
    elif s in ("@example", "example") and "firstname" in near:
        v = 5.0
    elif s == " protected" and "[email" in near:
        v = 11.0
    elif s in ("NAME", "EMAIL") and "<" in prev:
        v = 15.0
    elif s == "EMAIL":
        v = 10.0
    elif s in ("|", "||") and "ADDRESS" in near:
        v = 8.0
    elif s in ("_NUMBER", " Number") and "PHONE" in near.upper():
        v = 4.0
    return carry, float(v)

programs.sol:
"""Approximate the positive peaks with two local, readable patterns.

1. Invitations and intentions: 'let me/us', "let's", and 'I/we will'.
   'Let me' is stronger in a dialogue that has included tool messages.
2. Code-hosting addresses, especially the ending of github.com; ordinary
   .com endings get a much smaller response.

Small irregular activations elsewhere are left at zero. Keep a short text
suffix and a tool-dialogue flag, resetting both at document boundaries.
"""
import re

READS = ()
GITHUB = re.compile(r'(?:^|[\s/"\'])github$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, tail, tools = '', '', False
    else:
        _, previous, tail, tools = carry
    text = tail + token
    tools = tools or '<tool_' in text
    word = previous.strip()
    value = 0.0

    if word.lower() == 'let':
        if token == ' me':
            value = 0.75
            if word == 'Let':
                value = 0.91 if tools else 0.79
        elif token in ("'s", '’s'):
            value = 0.43
        elif token == ' us':
            value = 0.60
    elif word in ('I', 'we', 'We'):
        if token in (' will', "'ll", '’ll', ' shall'):
            value = 0.48 if word == 'I' else 0.34

    if token == '.com':
        value = 0.10
        if GITHUB.search(tail):
            value = 2.10 if tail.endswith('://github') else 1.65
            if previous.startswith('"'):
                value = 2.45
        elif tail.endswith('githubusercontent'):
            value = 1.90
    elif token == '/repos' and tail.endswith('api.github.com'):
        value = 0.88
    elif (token == '.in' and tail.endswith('gopkg')) or (
        token == '.org' and tail.endswith('bitbucket')
    ):
        value = 1.05

    return (doc, token, text[-64:], tools), value

programs.haiku:
"""Speaker's own next action. This component fires on the word that follows
"Let" or "I"/"we" when it announces what the speaker is about to do:
"Let me ..." (strongest), "Let's ...", "Let us ...", "I will", "I'll", "we will".
It also fires on ".com" right after "github" (github.com links).
Everywhere else it is near zero (small noise, not modelled)."""

READS = ()

LET = {"Let", " Let", "let", " let"}
SUBJECT_I = {"I", " I"}
SUBJECT_WE = {"We", " We", "we", " we"}
LET_OBJECT = {" me": 0.8, " us": 0.5, "'s": 0.4, "’s": 0.4}
FUTURE_I = {" will": 0.5, "'ll": 0.5, "’ll": 0.4, " shall": 0.55}
FUTURE_WE = {" will": 0.3, "'ll": 0.3, "’ll": 0.3, " shall": 0.5}
GITHUB = {"github", "ithub", '"github', " github", "/github", ".githubusercontent"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if len(prefix) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        prev = ""
    value = 0.0
    if prev in LET:
        value = LET_OBJECT.get(cur, 0.0)
    elif prev in SUBJECT_I:
        value = FUTURE_I.get(cur, 0.0)
    elif prev in SUBJECT_WE:
        value = FUTURE_WE.get(cur, 0.0)
    elif cur == ".com" and prev in GITHUB:
        value = 1.8
    return carry, float(value)

programs.sol:
"""A sparse negative response to markup and widget names.

Opening HTML names get negative values, especially form controls and images.
Closing names are usually weaker; a newline after an unfinished opening name is strong.
The same pattern covers DOM element creation, Vue directives, styled-widget
pieces, and regex alphabet ranges. Chinese reporter/editor byline labels
after opening parentheses also get a negative value. Initial words/numbers have a small
negative offset. Other positions are predicted as zero; lexical variation is omitted.
"""
import re

READS = ()
FORM = set('input button select textarea form'.split())
LAYOUT = set('div span p section article li ul ol header footer nav main'.split())
METADATA = set('link meta title style script head html body'.split())
VECTOR = set('circle ellipse polygon polyline line g defs'.split())
WIDGETS = set('Grid Stack Page Row Column Slider Border Canvas Visual Label '
              'Text View Input Button DatePicker ScrollView EditText TextView '
              'Rectangle Panel Menu Dialog'.split())
UI_ENDINGS = set('Button Input Section Text View Toggle Bar Panel Block '
                 'DatePicker ScrollView EditText TextView Modal '
                 'Component List Col'.split())
# Chinese news labels: reporter and responsible editor.
BYLINE_LABELS = {'记者', '责编'}


def strength(name):
    """Rough amplitudes for familiar kinds of element names."""
    if name in FORM:
        return 4.8
    if name == 'a':
        return 2.5
    if name == 'img':
        return 3.7
    if name == 'label':
        return 2.8
    if name == 'table':
        return 2.7
    if name in {'svg', 'rect'}:
        return 4.0
    if name == 'path':
        return 1.0
    if name in VECTOR:
        return 2.0
    if name == 'details':
        return 3.0
    if name in LAYOUT or name in METADATA:
        return 1.1
    if name in {'td', 'th', 'tr', 'tbody', 'thead'}:
        return 1.3
    if name in {'b', 'i', 'code', 'pre', 'blockquote', 'sup', 'sub'}:
        return 1.2
    if name in {'br', 'hr', 'template'} or re.fullmatch(r'h[1-6]?', name):
        return 0.7
    if name in WIDGETS:
        return 2.4
    return 0.0


def predict(s, recent, first):
    if first:
        word = s.strip()
        if word and word[0].isalpha():
            if word[0].isascii():
                return -0.36 if word[0].isupper() else -0.20
            return -0.22
        return -0.15 if word[:1].isdigit() else 0.0

    if s in BYLINE_LABELS and recent.endswith(('(', '（')):
        return -2.0

    if s in {'-z', '-Z'} and recent.endswith(('a', 'A')):
        bracket = recent.rsplit('[', 1)
        if len(bracket) == 2 and not re.search(r'[\]\s]', bracket[1]):
            return -2.2

    before = re.search(r'<(/?) *([A-Za-z0-9_:.-]*)$', recent)
    merged = re.match(r'^\s*<(/?)([A-Za-z][\w:.-]*)', s)
    if merged:
        closing, name = merged.groups()
        power = strength(name)
        if closing:
            return -0.85 if name == 'a' else -0.25 * power
        factor = 1.0 if name in FORM else 0.55 if name == 'img' else 0.8
        return -factor * power
    if before:
        closing, name = before.groups()
        # A '<' attached to an identifier usually opens a type parameter.
        if before.start() and recent[before.start()-1].isalnum():
            return 0.0
        power = strength(name)
        if s.isspace() and '\n' in s and name and not closing:
            widget = len(name) > 1 and name[0].isupper() and not name.isupper()
            return -7.0 if name == 'a' else -4.5 if power or widget else -0.3
        piece = re.match(r'[\w:.-]+', s)
        if piece:
            part = piece[0]
            if not name:
                if not part[0].isalpha():
                    return 0.0
                power = strength(part)
                if closing:
                    return -0.85 if part == 'a' else -0.25 * power
                return -power if power else -0.4
            complete = name + part
            if complete.isupper() and strength(complete.lower()):
                return -strength(complete.lower()) * (0.3 if closing else 1.0)
            if part == ':':
                return -0.8 if closing else -1.2
            if name.endswith(':') and part[0].isalpha():
                return -0.8
            if part in UI_ENDINGS:
                if closing:
                    return -1.2
                if part == 'Button':
                    return -3.0
                return -2.5 if part == 'Section' else -1.3
            if part.startswith('-'):
                return -0.4
            if closing:
                return -0.1
            if name == 'h' and part in {'1', '2', '3', '4', '5', '6'}:
                return -1.1
            return -0.4

    if s == ' src' and re.search(r'<img$', recent):
        return -0.8
    # Vue's conditional directives are names inside an unfinished tag.
    if re.search(r'<[^>]*\bv-?$', recent):
        if s in {'-', 'else', '-else'}:
            return -2.2
        if s.startswith('-'):
            return -0.7
    # Element names also occur as arguments to DOM construction routines.
    if re.search(r'(?:createElement|buildTag)\(\s*[\"\']$', recent):
        return -0.9 * strength(s)
    styled_part = s in UI_ENDINGS - {'Component', 'List', 'Col'}
    if styled_part and re.search(r'\bStyled\w*$', recent):
        return -0.7 if s == 'Toggle' else -2.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        recent, previous = '', ''
    else:
        _, recent, previous = carry
    value = predict(s, recent, not recent or previous == '<|endoftext|>')
    return (doc, (recent + s)[-100:], s), float(value)

programs.haiku:
"""Markup tag-name detector.

Fires on the element name of an HTML/JSX tag, as in '<img', '</td', '<script', '<Checkbox' or
'<StyledMenuModal'. Rules:
- the '<' must open a tag: it may not be glued to a preceding word (so List<String>, a<<b and
  email addresses do not count), and special tokens like <|im_end|> are skipped;
- the name is a known HTML element name or a capitalised component name;
- the name's later pieces (glued tokens: 'Styled' 'Menu' 'Modal') and the newline or space that
  closes the name in the opening tag take the same value."""

READS = ()

HTML_TAGS = set("""a abbr article aside audio b body br button canvas caption center code col dd div dl dt
em embed fieldset figcaption figure footer form frame h1 h2 h3 h4 h5 h6 head header hr html i iframe img
input label legend li link main map menu meta nav noscript object ol optgroup option p param pre
script section select small source span strong style sub sup table tbody td textarea tfoot th thead
time title tr u ul video template svg path g""".split())

NAME_VALUE = -1.0


def is_word(s):
    return len(s) > 0 and all(c.isalnum() or c in "_-." for c in s)


def is_tag_name(name):
    return is_word(name) and (name.lower() in HTML_TAGS or name[:1].isupper())


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    if len(toks) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        in_name = False
    else:
        in_name = bool(carry)
    prev = toks[-2] if len(toks) > 1 else ""
    # Later pieces of a name already open: glued word pieces, or the newline/space that ends it.
    if in_name:
        if is_word(cur) and cur[:1] not in (" ", "\n", "\t"):
            return True, NAME_VALUE
        if cur.strip() == "":
            return False, NAME_VALUE
        return False, 0.0
    # The '<' is inside the current token, e.g. '<img' or '</td'.
    if "<" in cur:
        i = cur.index("<")
        before = cur[i - 1] if i > 0 else prev[-1:]
        name = cur[i + 1:].lstrip("/")
        if not (before.isalnum() or before == "_" or name.startswith("|")) and is_tag_name(name):
            return True, NAME_VALUE
        return False, 0.0
    # The '<' ends the previous token, e.g. ' <' then 'img', or '</' then 'td'.
    if cur[:1] in (" ", "\n", "\t") or not is_word(cur):
        return False, 0.0
    if prev.endswith("</"):
        core = prev[:-2]
    elif prev.endswith("<"):
        core = prev[:-1]
    else:
        return False, 0.0
    before = core[-1:] if core else (toks[-3][-1:] if len(toks) > 2 else "")
    if not (before.isalnum() or before == "_") and is_tag_name(cur):
        return True, NAME_VALUE
    return False, 0.0

programs.sol:
"""Approximate a subword spelling contrast, not a map-topic classifier.

Map spellings are positive; rap/trap/clap/strap spellings are negative.
A separately tokenized 'ap' has a larger response than a whole word, so
remember the unfinished word. Longer, complete words are mostly ignored.
Repeated middle dots and a few non-Latin map spellings are secondary cases.
"""
import re

READS = ()

# Consonants before 'ap': response for an entire piece, then for split 'ap'.
ONSETS = {
    'str': (-5.0, -9.0), 'scr': (-4.5, -7.0),
    'sc': (-3.3, -6.7), 'cl': (-3.3, -7.0), 'sl': (-4.1, -6.4),
    'fl': (-3.1, -5.3), 'tr': (-2.1, -6.0),
    'cr': (-4.5, -6.2), 'sn': (-1.8, -2.8),
    'gr': (0.0, 0.0), 'r': (-1.9, -3.2),
    'l': (-2.4, -3.0), 'n': (-1.6, -1.6),
    't': (-1.5, -1.9), 'c': (-0.3, -1.7),
}
ENDINGS = {'', 's', 'p', 'ping', 'pings', 'ped', 'per', 'pers',
           'h', 'er', 'e', 'pe', 'pen', 'es', 'o', 'a', 'i', 'le'}


def response(raw, previous):
    s = raw.lower()
    if len(raw) > 1 and not raw.strip('·'):
        return 2.89
    if raw.strip() in {'地图', '地圖', 'マップ'}:
        return 1.4
    if raw == '射' and previous.endswith('映'):
        return 5.4
    if raw == 'ップ':
        return 8.0 if previous.endswith('マ') else (
            -4.0 if previous.endswith('ラ') else 0.0)
    k = s.find('ap')
    if k < 0:
        return 0.0
    ending = s[k + 2:]
    if ending not in ENDINGS:
        return 0.0
    local = re.search(r'[a-z]*\Z', s[:k]).group()
    split = k == 0
    if split and raw.startswith('Ap'):
        return 0.0
    stem = re.search(r'[a-z]*\Z', previous.lower()).group() if split else local
    if not stem:
        return 0.0
    if stem.endswith('m'):
        if split:
            return {'': 7.9, 's': 11.3, 'ping': 5.4, 'pings': 3.3,
                    'per': 3.9, 'ped': 3.6, 'h': 4.6}.get(ending, 2.0)
        # Short vowel+map pieces commonly finish compound names (e.g. sourcemap).
        if len(local) > 1:
            return (7.9 if local == 'em' else 5.8) if (
                len(local) <= 4 and local[-2] in 'aeiou') else 0.5
        leading = s[:k - 1]
        capital = raw[k - 1:k + 2]
        spaced = bool(leading and leading[0].isspace())
        value = 1.3 if spaced else 1.8
        if capital.isupper():
            value = 2.5 if spaced else 4.0
        elif capital[0].isupper() and not spaced:
            value = 3.0
        if leading.endswith('-'):
            value = 5.5
        elif leading.endswith('/'):
            value = 3.0
        elif leading.endswith('.'):
            value = 4.2 if capital[0].isupper() else 1.6
        elif leading.endswith(('_', '(')):
            value = 1.0 if capital[0].isupper() else 1.5
        if ending:
            value = {'s': value * (0.85 if spaced else 1.3),
                     'ping': 2.3 if spaced else 1.7, 'pings': 1.3,
                     'ped': 1.2, 'per': 2.0, 'pers': 1.8,
                     'le': 2.0 if capital[0].isupper() else 3.2}.get(ending, 0.2)
        return value
    onset = next((c for c in ONSETS if stem.endswith(c)), None)
    if onset is None:
        return -0.5 if split and ending in {'', 's', 'h'} else 0.0
    if not split and len(local) > len(onset):
        return 0.0
    value = ONSETS[onset][int(split)]
    if (split and raw.isupper()) or (not split and raw[:1].isupper()):
        value *= 1.4
    if not split and raw[:1].isspace() and onset in {'l', 'n', 't', 'c', 'cr'}:
        value = {'l': -0.6, 'n': 0.0, 't': -0.45, 'c': 0.0, 'cr': -0.4}[onset]
    strong = onset in {'str', 'scr', 'cl', 'sl', 'fl', 'tr', 'cr'}
    if ending == 'e':
        value *= 0.1 if split else 0.45
    elif ending == 's':
        value *= 0.8 if split else (0.55 if onset == 'scr' else 1.0)
    elif ending == 'h':
        value *= 1.4 if onset == 't' else 0.33
    elif ending.startswith('p'):
        value *= (1.1 if ending == 'ping' else 0.75) if strong else 0.45
    elif ending:
        value *= 0.4 if split else 0.1
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    value = response(raw, previous)
    return (doc, (previous + raw)[-32:]), float(value)

programs.haiku:
"""Component layers.1.mlp.down_proj:3575: a detector for the spelling "map", with a
"-lap / -rap" counterweight.

What it does, in plain terms:
- Positive on the word "map" when it is one token: "map", " map", "Map", " Map", " MAP",
  "maps", "mapping", "_map", ".map", "maple". About +1.5 in lower case; about +2.4 when
  capitalised or upper case.
- Positive on a bare "ap" (or "aps", "AP") that completes an "m" from the token before,
  so "m" + "ap" spells "map": "sitem|ap", "IM|ap". About +9.
- Negative on a bare "ap" that completes an "l" or "r": "Cl|ap", "Sl|ap", "tr|ap". About -4.
- Negative on whole words "rap", "trap", "flap", "snap", "lap", "clap", "slap": about -1.7.
- Mildly negative (about -0.7) on other bare "ap", "aph" and "ape" fragments.
- Positive, about +2.9, on a middle dot that continues a run of middle dots ("········").
  This was seen in one long run of dots in the training sample; a single dot gives 0.
- Zero everywhere else. Ordinary words such as " approach", " app", " cap", " HashMap"
  give about 0.

Values are the mean activation of each class over about 6,000 training rows. The program
reads only the current token and the one before it, so it has no state.
"""

READS = ()

MAP_WORDS = {"map", "maps", "mapping", "mappings", "mapped", "maple", "treemap"}
LAP_WORDS = {"rap", "trap", "flap", "snap", "lap", "clap", "slap"}


def _core(s):
    return s.strip(" _.(\"'`/-").lower()


def _is_dots(s):
    return bool(s.strip()) and set(s.strip()) == {"\u00b7"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    core = _core(cur)
    if core in MAP_WORDS:
        return carry, (2.4 if cur.strip(" _.(\"'`")[:1].isupper() else 1.5)
    if cur.strip() in ("ap", "aps", "AP", "APs") and not cur.startswith(" "):
        if prefix.position == 0:
            return carry, -0.7
        prev = _core(prefix.token_strings[-2])
        if prev.endswith("m"):
            return carry, 9.0
        if prev.endswith(("l", "r")):
            return carry, -4.0
        return carry, -0.7
    if core in ("aph", "ape"):
        return carry, -0.7
    if core in LAP_WORDS:
        return carry, -1.7
    if _is_dots(cur) and prefix.position > 0 and _is_dots(prefix.token_strings[-2]):
        return carry, 2.9
    return carry, 0.0

programs.sol:
"""A sparse approximation of content-introducing boundaries.

Strong training responses include attributed clauses, chat/code separators,
file-header markers and first indentation. These rules capture that pattern.
Most token-specific background variation is left at zero; unmatched document
starts receive a negative average offset.
"""
import re
from functools import lru_cache
import wordnet
import cedict

READS = ()


@lru_cache(maxsize=8192)
def word_class(word):
    """Dictionary classes for words that can introduce a statement."""
    if 'say' in wordnet.base_forms(word, 'verb'):
        return 'say'
    if ('verb.communication' in wordnet.categories(word, 'verb')
            and any(wordnet.is_a(word, k) for k in ('say', 'inform', 'show'))):
        return 'report'
    if any(wordnet.is_a(word, k) for k in ('think', 'learn', 'discover')):
        return 'mental'
    return ''


@lru_cache(maxsize=4096)
def chinese_report(tail):
    # A reporting verb can be followed by its audience: "told reporters".
    tail = re.sub(r'(记者|記者|我们|我們|他们|他們)$', '', tail)
    gloss = ''
    for n in range(min(4, len(tail)), 0, -1):
        entries = cedict.glosses(tail[-n:])
        if entries:
            if n > 1 or tail[-1] in '说說曰云指':
                gloss = ' '.join(entries)
            break
    if re.search(r'to (forecast|predict)', gloss):
        return 1.3
    if re.search(r'to (believe|think|consider)', gloss):
        return 0.7
    if re.search(r'to (say|tell|speak|state|indicate|express|announce|declare|'
                 r'point out|learn|discover|find out|emphasize|show|explain|'
                 r'report|mention)', gloss):
        return 0.46
    return 0.0


def predict(context, token, previous, position, seen):
    stripped = token.strip()
    words = []
    if stripped in ('that', ',', '),'):
        words = re.findall(r"[A-Za-z]+(?:'[A-Za-z]+)?", context[-180:].lower())
    last = words[-1] if words else ''

    # Explicit content boundaries in chat and formatted text.
    if token == '\n' and previous in ('user', 'assistant', '<|im_end|>'):
        return {'user': 0.31, 'assistant': 0.06, '<|im_end|>': -0.05}[previous]
    if token.startswith('\n') and previous in ('<think>', '</think>'):
        return 0.44 if previous == '<think>' else 0.38
    if '\n' in token and re.search(r'`{3,}\r?\n', context[-8:] + token):
        return 0.76
    if token in ('\n', '\n\n') and previous.rstrip().endswith('$$'):
        return 0.32
    if stripped in ('<', '"') and re.search(r'#\s*include$', context):
        return 1.31
    if stripped == 'php' and context.endswith('<?'):
        return 2.94
    if stripped == '#"' and context.endswith('r'):
        return 1.4
    if stripped == '@@':
        return 0.63 if token.startswith(' ') else 0.09

    # Complementizers and punctuation after attribution expressions.
    if stripped == 'that' and token.startswith(' '):
        if last == 'fact':
            return -0.22
        if re.search(r'\b(turn\w*|point\w*) out$', context.lower()):
            return 1.17
        kind = word_class(last)
        if kind:
            return {'say': 0.20, 'report': 0.11, 'mental': 0.05}[kind]
        if last in ('clear', 'obvious', 'apparent', 'evident', 'certain'):
            return 0.18
        if last not in ('and', 'of', 'in', 'like', 'given', 'provided', 'than',
                        'not', 'for', 'with', 'without', 'so', 'the', 'such'):
            if any(word_class(w) in ('say', 'report') for w in words[-8:-1]):
                return 0.05
        return -0.02
    if token in (' que', ' che', ' أن', ' ان'):
        return {'que': 0.15, 'che': 0.29, 'أن': 0.44, 'ان': 0.26}[stripped]
    if token == ' что':
        return 0.37 if previous == ',' else 0.0
    if stripped in (',', '),'):
        if re.search(r'\baccording to\b[^,;.!?\n]{0,100}$', context.lower()):
            return 0.47
        if re.search(r'\bas\b[^,;.!?\n]{0,80}$', context.lower()):
            if word_class(last) or last in ('above', 'earlier', 'out'):
                return 0.19
    if token == '，':
        return chinese_report(context[-10:])

    # An introduced listing, or the first occurrence of an indentation run.
    if token and set(token) <= set(' \t'):
        if context.endswith(('\n', '\r')):
            line = context.rstrip('\r\n').rsplit('\n', 1)[-1]
            if re.search(r'(?:[/\\][^\s:]+|\.[A-Za-z]{1,5}):$', line):
                return 0.87
            if previous.rstrip('\r\n') == ':':
                return 0.34 if token not in seen else 0.07
            if not seen:
                return 0.42
            return 0.11 if token not in seen else 0.0
        return 0.0
    if token == '\n\n':
        return 0.09
    if position == 0 and token == 'using':
        return 2.86
    return -0.17 if position == 0 else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '', 0, frozenset())
    _, recent, previous, position, seen = carry
    token = prefix.token_strings[-1]
    context = recent.decode('utf-8', errors='ignore')
    value = predict(context, token, previous, position, seen)
    if token and set(token) <= set(' \t') and context.endswith(('\n', '\r')):
        seen = seen | {token}
    recent = (recent + prefix.token_bytes[-1])[-800:]
    return (doc, recent, token, position + 1, seen), value

programs.haiku:
"""layers.1.mlp.down_proj:3576: a sparse, signed rule-based guess (v3).

Almost everywhere the component is near 0. Its large values come from a few kinds of place:

- the first token of a document (or of a packed row): negative for most words and
  punctuation, positive for a tab, a newline, or "that";
- "that" right after a verb of saying, showing or finding ("shows that"): positive;
- the words that open a reported clause in other languages (что, أن, إن, ว่า, že, che, que);
- a closing code fence, the double newline after a think tag, the token right after
  "#include", and an indented first line after a line ending in a colon.

Every other position is predicted as 0.
"""
READS = ()

# verbs that introduce a reported clause ("said that", "shows that", "found that")
REPORTING = {"said", "say", "says", "show", "shows", "showed", "shown", "found", "find",
             "suggest", "suggests", "suggested", "reported", "report", "told", "claimed",
             "believe", "noted", "indicates", "revealed", "confirmed", "explained", "out"}
# complementizers meaning "that" in other languages: Russian, Arabic, Thai, Slavic, Italian
OTHER_THAT = {"что": 0.4, "أن": 0.4, "إن": 0.5, "่า": 0.7, "že": 0.8, "che": 0.3,
              "que": 0.15, "att": 0.25}


def start_value(tok):
    """Value at the first token of a document: depends only on the token itself."""
    s = tok.strip()
    if "\t" in tok:
        return 0.7
    if "\n" in tok:
        return 0.15
    if s == "that":
        return 1.4
    if s.isdigit() or s == ",":
        return 0.0
    return -0.2


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    s = tok.strip()
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    new_doc = len(prefix.token_strings) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        return carry, start_value(tok)
    if s == "that":
        return carry, 0.3 if prev.strip() in REPORTING else 0.0
    if s in OTHER_THAT:
        return carry, OTHER_THAT[s]
    if tok in ("`\n\n", "`\n"):
        return carry, 0.6 if tok == "`\n\n" else 0.3
    if prev == "#include" and tok in (" <", ' "'):
        return carry, 1.3
    if prev in ("<think>", "</think>") and tok == "\n\n":
        return carry, 0.4
    if tok == "\n\n":
        return carry, 0.1
    if prev.endswith(":\n") and s == "" and tok:
        return carry, 0.2
    return carry, 0.0

programs.sol:
"""Sparse character-fragment and document-opening responses.

These are separate observed response families, not one semantic topic. Named
Indic consonants and certain broken-up Korean syllables are negative; circled
numerals, decorative dots and some emoji fragments are positive. Opening
numerals, function words, declarations and punctuation have separate rules.
Most text gets nearly zero. Byte history identifies split characters; an
incomplete three-byte character is classified by the start of its possible
codepoint range, never by an unseen continuation. State resets per document.
"""
import unicodedata as ud

READS = ()
BASE = -0.0008
INITIAL_DIGITS = (0.40, 0.54, 0.16, -0.03, 0.20,
                  0.09, 0.28, 0.30, 0.47, 0.37)
ARTICLES = {'a', 'an', 'the'}
PREPOSITIONS = {'at', 'by', 'for', 'from', 'in', 'into', 'of', 'on', 'to', 'with'}
AUXILIARIES = {
    'can', 'could', 'may', 'might', 'must', 'shall', 'should', 'would',
    'is', 'are', 'was', 'were', 'be', 'been', 'have', 'has', 'had',
    'do', 'does', 'did'
}
FUNCTION_WORDS = ARTICLES | PREPOSITIONS | AUXILIARIES

# Isolated letters, or the byte fragment that completes them.
LETTERS = {
    'ਣ': -4.94,  # Gurmukhi retroflex nasal, NNA
    'ੜ': -3.85,  # Gurmukhi retroflex flap, RRA
    'ड': -4.65,  # Devanagari voiced retroflex stop, DDA
    'ட': -3.30,  # Tamil retroflex stop, TTA
    'ژ': -1.40,  # Persian JEH
    'ņ': -2.10,  # Latin n with cedilla
    'ษ': -1.80,  # Thai SO RUSI
}
# These responses apply only when the character ends in a separate byte token.
FRAGMENT_ENDINGS = {
    'ţ': -0.70,  # Latin t with cedilla
    'ち': -0.85,  # Hiragana CHI
    'ḣ': -1.15,  # Latin h with dot above
    '🔥': 1.70,  # Fire
    '🔎': 0.95,  # Right-pointing magnifying glass
}
OPENING_PUNCTUATION = {
    ' .': 2.33, '.\n': 0.62, '.\n\n': 0.62, '--': 1.35,
}


def final_character(data):
    """Last completed character, or the lower bound of an incomplete range."""
    i = len(data) - 1
    while i > 0 and data[i] & 192 == 128:
        i -= 1
    tail = data[i:]
    try:
        return tail.decode('utf8'), False
    except UnicodeDecodeError:
        if len(tail) == 2 and 224 <= tail[0] < 240:
            try:
                return (tail + b'\x80').decode('utf8'), True
            except UnicodeDecodeError:
                pass
    return '', False


def korean_fragment(char, unfinished, old):
    syllable = ord(char) - 0xac00
    onset, vowel, coda = syllable // 588, (syllable // 28) % 21, syllable % 28
    # The standard Hangul order gives onset, medial vowel and final consonant.
    if unfinished and old.endswith((b' \xeb', b' \xed')):
        if onset == 4:  # Doubled D
            return -2.25
        if onset in (5, 6):  # RIEUL, MIEUM
            return -1.3
        if onset == 7:  # BIEUP, stronger with rounded vowels
            return -1.5 if 8 <= vowel <= 16 else -0.65
        if onset == 8:  # Doubled B
            return -0.95
        if onset == 18:  # HIEUH, stronger in high-vowel fragments
            return -1.35 if vowel >= 17 else -0.8
        if onset in (2, 3):  # N, D
            return -0.35
    elif not unfinished:
        if onset in (4, 8) and coda == 0 and vowel in (0, 4):
            return -1.4  # Open doubled-D/B syllables with A or EO
        if onset in (6, 7) and coda in (19, 23):
            return -1.35  # Bilabial onset, sibilant final consonant
    return BASE


def character_response(char, unfinished, raw, old, previous_letter):
    fragment = len(raw) == 1 and 128 <= raw[0] < 192
    text = raw.decode('utf8', 'replace')
    single = len(text) == 1 and text != '\ufffd'
    if len(char) != 1 or not (single or fragment):
        return BASE
    if char in LETTERS:
        return LETTERS[char]
    if char == '़' and previous_letter == 'ड':  # DDA followed by nukta
        return -3.8
    name = ud.name(char, '')
    if fragment:
        if char in FRAGMENT_ENDINGS:
            return FRAGMENT_ENDINGS[char]
        if unfinished and name.startswith('SINHALA '):
            return -1.75
        if 0xac00 <= ord(char) <= 0xd7a3:
            return korean_fragment(char, unfinished, old)
    if name.startswith('CIRCLED DIGIT '):
        number = ud.numeric(char)
        return 2.9 / (number + 0.3) if number <= 3 else 1.6
    return BASE


def opening_response(text, default):
    word = text.strip().lower()
    if len(text) == 1 and text in '0123456789':
        return INITIAL_DIGITS[int(text)]
    if word in FUNCTION_WORDS:
        return -0.45
    if word in {'we', 'they'}:
        return -0.6
    if word in {'package', 'namespace', '#include'}:
        return -0.9
    if word == 'const':
        return 1.38
    if word == 'using':
        return 0.54
    if text in OPENING_PUNCTUATION:
        return OPENING_PUNCTUATION[text]
    if text.isspace() and '\n' in text:
        return 0.34
    if word and set(word) == {'#'}:
        return -0.4
    return default


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        old, position, first, opening, previous_letter = b'', 0, None, True, ''
    else:
        _, old, position, first, opening, previous_letter = carry
    raw = prefix.token_bytes[-1]
    text = raw.decode('utf8', 'replace')
    char, unfinished = final_character(old + raw)
    if first is None:
        first = raw
    opening = opening and raw == first
    value = character_response(char, unfinished, raw, old, previous_letter)
    if len(text) >= 2 and set(text) == {'·'}:
        value = 0.84
    if len(text.strip()) >= 6 and set(text.strip()) == {':'}:
        value = 1.9
    if text == '://':
        value = 0.16
    elif text.strip() == '//' and old.rstrip().endswith(b':'):
        value = 1.5
    if opening:  # Includes a document's initial run of identical tokens.
        value = opening_response(text, value)
    if position == 1 and first == b'1' and raw == b'2':
        value = -2.37  # Second digit of a document-opening 12.
    if len(char) == 1 and not unfinished:
        previous_letter = char
    state = (doc, (old + raw)[-3:], position + 1,
             first, opening, previous_letter)
    return state, value

programs.haiku:
"""Separators inside a list of short items.

The component sits on the punctuation and conjunctions that join items in a list:
- a comma closes an item. It is strongly positive when the item just before it is one or
  two tokens long and the list has already had a comma (as in "wide, tall, and ..." or
  "Ab, Bi, Mb"). The positive value fades as the item gets longer, and is about zero for
  commas that open a clause or follow long items.
- a conjunction (and, or, nor, y, e, et, und, ou, ve, и) right after a short list item is
  negative, the mirror image of the comma: "X, Y and ...". Without a list in view it is zero.
- dashes, closing quotes and tags carry a small constant positive value; backticks a small
  negative one. These are minor.

Everything else predicts 0. Only the current token and the tokens back to the previous
comma (at most 8 tokens, same document, no sentence break) are read.
"""

READS = ()

# comma: activation by tokens between it and the previous comma (1 token = gap 2)
COMMA_BY_GAP = {2: 1.3, 3: 0.75, 4: 0.3, 5: 0.12}
# conjunction after a short item: negative, same gap rule
CONJ_BY_GAP = {2: -1.1, 3: -0.8, 4: -0.5, 5: -0.5, 6: -0.25, 7: -0.25}
CONJUNCTIONS = {" and", " or", " nor", " y", " e", " et", " und", " ou", " ve", " и", " و"}
DASHES_AND_CLOSERS = {" —", "—", "”", "</", " },"}
BACKTICKS = {" `", "`"}
LOOKBACK = 8


def gap_to_comma(prefix):
    """Tokens since the last comma, or None if there is none within LOOKBACK tokens of this
    document or a sentence or line break came first."""
    t = prefix.position
    for k in range(t - 1, max(-1, t - LOOKBACK - 1), -1):
        if prefix.document_ids[k] != prefix.document_ids[t]:
            return None
        if prefix.token_strings[k] in (".", "\n"):
            return None
        if prefix.token_strings[k] == ",":
            return t - k
    return None


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    gap = gap_to_comma(prefix)
    value = 0.0
    if token == ",":
        value = COMMA_BY_GAP.get(gap, 0.0)
    elif token in CONJUNCTIONS:
        value = CONJ_BY_GAP.get(gap, 0.0)
    elif token in DASHES_AND_CLOSERS:
        value = 0.35
    elif token in BACKTICKS:
        value = -0.25
    return carry, float(value)

programs.sol:
"""Negative word-onset signal for short fragments rather than whole words.

English frequency mass on words sharing a spelling estimates how prefix-like a
spelling is. Lowercase short fragments in prose get the strongest response.
Capitals, non-English contexts and mathematical/code notation reduce it.
Single-letter Cyrillic onsets have a separate frequency-based rule. A bounded
preceding-text window resets at each document boundary.
"""
import math
import re
import regex
from collections import defaultdict
from functools import lru_cache
from wordfreq import top_n_list, word_frequency, zipf_frequency

READS = ()
LANGUAGES = ('en', 'de', 'fr', 'es', 'it', 'pt', 'nl', 'ru', 'pl', 'tr')
PREFIXES = set('''
anti auto bi co counter de dis en em ex extra fore hyper hypo il im in
inter intra ir macro micro mid mis mono multi neo non over pan para peri
poly post pre pro pseudo re semi sub super supra tele trans tri ultra un
under uni up self
'''.split())

# Sum ordinary word frequencies under each spelling prefix.
PREFIX_MASS = defaultdict(float)
for word in top_n_list('en', 100000):
    if word.isalpha():
        probability = word_frequency(word, 'en')
        for length in range(1, min(len(word), 12) + 1):
            PREFIX_MASS[word[:length]] += probability

@lru_cache(maxsize=50000)
def spelling(word):
    frequency = word_frequency(word, 'en')
    gap = math.log10(1 + PREFIX_MASS[word] / max(frequency, 1e-8))
    return gap, zipf_frequency(word, 'en')

@lru_cache(maxsize=50000)
def language_evidence(word):
    return tuple(max(0, zipf_frequency(word, lang) - 3)
                 for lang in LANGUAGES)

def response(token, before):
    word = token.strip()
    if not token.startswith(' ') or not word.isalpha():
        return -0.005
    gap, frequency = spelling(word.lower())
    if gap <= 0.861:
        if not regex.search(r'\p{Script=Cyrillic}', word):
            return -0.005
        if len(word) > 1:
            return -0.014
        if frequency > 2.152:
            return -0.094
        return -1.106 if word.islower() else -0.020

    words = re.findall(r'[^\W\d_]+', before[-350:].lower())[-20:]
    evidence = [0.] * len(LANGUAGES)
    for previous in words:
        if len(previous) > 1:
            for i, score in enumerate(language_evidence(previous)):
                evidence[i] += score
    english = evidence[0] / max(1, len(words))
    margin = (evidence[0] - max(evidence[1:])) / max(1, len(words))
    productive = word.lower() in PREFIXES
    if gap <= 1.722:
        if margin <= 0.742:
            return -0.017
        if not productive:
            return -0.138
        return -1.323 if word.islower() else -0.223

    # Single-letter words other than 'a' and 'I' suggest variable notation.
    recent = re.sub(r'<\|[^>]*\|>', '', before[-120:])
    recent_words = re.findall(r'[^\W\d_]+', recent.lower())[-16:]
    variables = sum(len(w) == 1 and w not in ('a', 'i')
                    for w in recent_words) / max(1, len(recent_words))
    code = any(c in '_{};=\\' for c in recent[-70:])
    math_notation = any(c in '=+*^{}\\' for c in recent[-55:])
    if english <= 1.771:
        if frequency <= 4.681:
            return -0.038 if margin <= 0.662 else -0.259
        if variables > 0.126:
            return -0.045
        if code:
            return -0.137
        return -0.396 if gap <= 2.234 else -0.650
    if not word.islower():
        if len(word) > 1:
            return -0.149
        return -0.651 if variables <= 0.025 else -0.265
    if len(word) > 3:
        return -0.349
    if math_notation:
        return -0.082
    if productive:
        return -2.187
    if variables > 0.117:
        return -0.426
    if gap <= 2.234:
        previous_frequency = zipf_frequency(words[-1], 'en') if words else 0
        return -0.760 if previous_frequency <= 5.834 else -1.250
    if frequency <= 3.276:
        return -1.084
    # Numerals alone are a weaker mathematical cue than explicit operators.
    numerical = any(c in '=+*/^_{}\\0123456789' for c in before[-80:])
    if not numerical:
        return -1.794
    return -1.738 if frequency <= 4.119 else -0.981

def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    before = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = response(token, before)
    return (document, (before + token)[-500:]), float(value)

"""Approximate a sparse mixture of spelling and construction responses.

Alignment/completeness spellings (齐, 齊, 揃, そろ) and encounter verbs
are positive. Chinese result complements, impressions and comparisons are
negative. A few Cyrillic continuations and Indic vowel spellings have their
own responses. At document starts, a small word-shape rule replaces these
context-dependent detectors. Unrecognized tokens stay near zero.
"""
import regex
from opencc import OpenCC
from functools import lru_cache

READS = ()
_SIMPLIFY = OpenCC('t2s')
_CYRILLIC = regex.compile(r'^\p{Script=Cyrillic}+$')


@lru_cache(maxsize=65536)
def simplify(text):
    return _SIMPLIFY.convert(text)


def start_value(token):
    """The first token has a weaker, mostly word-shape-dependent response."""
    word = token.strip()
    value = 0.07
    if len(word) >= 4:
        value -= 0.19
    if regex.search(r'\p{Script=Han}', word):
        value -= 0.40
    if word and word[0].isupper():
        value -= 0.23
    if word.isdecimal():
        value -= 0.11
    if word.isupper():
        value += 0.18
    if regex.search(r'\p{Script=Cyrillic}', word):
        value += 0.16
    if word.lower() in {'is', 'was', 'were', 'are', 'be', 'been', 'am', 'being'}:
        value += 0.20
    if word.startswith('#'):
        value -= 0.40
    if word == ';':
        value += 0.33
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    previous = '' if reset else carry[1]
    token = prefix.token_strings[-1]
    tail = b'' if reset else carry[2]
    raw = tail + prefix.token_bytes[-1]
    # Keep enough bytes for a split character or an Indic syllable.
    new_carry = (doc, token, raw[-6:])
    if reset:
        return new_carry, start_value(token)
    word = simplify(token)
    value = 0.002
    if raw.endswith(('ు'.encode('utf8'), 'று'.encode('utf8'))):
        # Telugu short-u sign, or the Tamil syllable rru.
        value = -3.6
    elif raw.endswith('揃'.encode('utf8')):
        value = 10.9
    elif token == 'ろ' and previous.endswith('そ'):
        value = 7.8
    elif previous[-1:] + token in {'ずら', 'ズレ', 'ぞれ'}:
        value = 3.0
    elif (word == '齐' or
          raw.endswith(('齐'.encode('utf8'), '齊'.encode('utf8')))):
        value = 3.0 if simplify(previous) == '一' else 8.5
    elif word == '整齐':
        value = 4.0
    elif word == '遭' or raw.endswith('遭'.encode('utf8')):
        # 周遭 means surroundings, not undergoing an event.
        value = 1.0 if simplify(previous) == '周' else 4.5
    elif word == '遭到':
        value = 4.5
    elif word == '遭遇':
        value = 2.2
    elif word == '遇到':
        value = 1.3
    elif word == '遇':
        value = 1.2
    elif word == '受到':
        value = 1.1
    elif word == '起来':
        sensory = {'吃', '尝', '读', '听', '闻', '摸'}
        value = -7.5 if simplify(previous) in sensory else -2.6
    elif word in {
        '看起来', '听起来', '读起来', '闻起来', '尝起来', '摸起来', '吃起来'
    }:
        value = -3.6
    elif word == '了起来':
        value = -1.7
    elif word == '下来':
        value = -1.4
    elif word == '看上去':
        value = -3.1
    elif word in {'感觉', '看来'}:
        value = -1.3
    elif word == '显得':
        value = -0.7
    elif word == '变得':
        value = -0.4
    elif word == '相比':
        value = -1.5
    elif word == '来说':
        value = -0.55
    elif word in {'来', '去', '上去'} and simplify(previous) == '看':
        value = -3.3
    elif token == '感じ':
        value = -0.6
    elif token == '比べ':
        value = -1.4
    elif _CYRILLIC.fullmatch(token):
        before, current = previous.lower(), token.lower()
        if before.strip() == 'з':
            if current in {'р', 'ря'}:
                value = 5.0
            elif current.startswith('р'):
                value = 1.3
            elif current.startswith(('в', 'л', 'м', 'б', 'г')):
                value = 1.4
            elif current.startswith('д'):
                value = 0.5
        elif before.endswith('з'):
            value = 3.5 if current == 'р' else 0.15
        elif before.endswith('зв') and current == 'р':
            value = 3.0
    return new_carry, value

programs.haiku:
"""Concept-word program for layers.1.mlp.down_proj:3583.

The component is sparse and mostly quiet: on most tokens it is near zero, and its large
values sit on a few Chinese words. This program predicts a value only for those words and
0 elsewhere:

- Negative on verb complements meaning "up / down, into a new state" (起来, 下来, 上去),
  and on verbs of seeming or feeling (感觉, 看来, 似乎, 显得, 看起来).
- Positive on verbs of meeting or suffering (遭, 遭遇, 遭到 strongest; 遇, 遇到, 受到 weaker),
  and on words of completeness or togetherness (齐 strongest; 足, 够, 全体, 充足 weaker).
"""

READS = ()

RISE_FALL = {"起来", "起來", "下来", "下來", "上去"}
SEEMING = {"感觉", "感覺", "感到", "看来", "看來", "似乎", "显得", "顯得", "看起来", "看起來", "听起来", "聽起來", "看上去"}
SUFFER_STRONG = {"遭", "遭遇", "遭到"}
SUFFER_WEAK = {"遇", "遇到", "受到"}
TOGETHER = {"齐", "齊"}
COMPLETE = {"足", "够", "全体", "充足", "整齐"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word in RISE_FALL:
        return None, -2.5
    if word in SEEMING:
        return None, -2.0
    if word in SUFFER_STRONG:
        return None, 3.0
    if word in TOGETHER:
        return None, 7.0
    if word in SUFFER_WEAK or word in COMPLETE:
        return None, 1.0
    return None, 0.0
